# Every format lyric_formats reads: TTML, LRC and enhanced LRC, ASS, KRC,
# QRC, YRC, LYS, SRT and plain text.
LYRIC_SUFFIXES = LF.READS
IMAGE_SUFFIXES = (".png", ".jpg", ".jpeg", ".webp", ".bmp", ".gif", ".avif")


def image_format(raw: bytes) -> str | None:
    """The format named by its first bytes, for loadFromData: without one, Qt
    loads every image plugin to ask (+11MB here, 2026-10-17). None: ask."""
    head = bytes(raw[:16])
    if head.startswith(b"\xff\xd8\xff"):
        return "JPG"
    if head.startswith(b"\x89PNG"):
        return "PNG"
    if head.startswith(b"GIF8"):
        return "GIF"
    if head[:4] == b"RIFF" and head[8:12] == b"WEBP":
        return "WEBP"
    return None


def _droppable(url) -> str:
    """"lyric", "image" or "" for a dropped URL."""
    path = url.toLocalFile()
    if not path:
        return ""
    end = pathlib.Path(path).suffix.lower()
    if end in LYRIC_SUFFIXES:
        return "lyric"
    return "image" if end in IMAGE_SUFFIXES else ""


_CHAN: list = []


def _channel_levels() -> list:
    """What QColor.redF says for each of the 256 values a channel can take.

    Asked of Qt rather than divided by 255: Qt 6 answers in single precision,
    and a sum of a thousand of them comes out in a different eighth decimal
    from one of doubles.
    """
    if not _CHAN:
        _CHAN.extend(QColor(v, v, v).redF() for v in range(256))
    return _CHAN


def luma_of(img: QImage) -> float:
    """How bright the cover is, 0 to 1: the plain average, black pixels
    included."""
    small = img.scaled(32, 32, Qt.AspectRatioMode.IgnoreAspectRatio,
                       Qt.TransformationMode.SmoothTransformation)
    n = small.width() * small.height()
    if not n:
        return 0.4
    total = 0.0
    if not small.hasAlphaChannel():
        rgba = small.convertToFormat(QImage.Format.Format_RGBA8888)
        bits = rgba.constBits().asarray(rgba.sizeInBytes())
        line = rgba.bytesPerLine()
        lv = _channel_levels()
        for y in range(rgba.height()):
            i = y * line
            for _x in range(rgba.width()):
                total += (0.2126 * lv[bits[i]] + 0.7152 * lv[bits[i + 1]]
                          + 0.0722 * lv[bits[i + 2]])
                i += 4
        return total / n
    for y in range(small.height()):
        for x in range(small.width()):
            c = small.pixelColor(x, y)
            total += 0.2126 * c.redF() + 0.7152 * c.greenF() + 0.0722 * c.blueF()
    return total / n


def palette_of(img: QImage, want: int = 4) -> list[QColor]:
    """Dominant colours by a coarse hue/sat/value histogram, near-black and
    near-grey pixels dropped."""
    small = img.scaled(48, 48, Qt.AspectRatioMode.IgnoreAspectRatio,
                       Qt.TransformationMode.SmoothTransformation)
    buckets: dict[tuple, list] = {}
    for y in range(small.height()):
        for x in range(small.width()):
            c = small.pixelColor(x, y)
            h, s, v, _ = c.getHsv()
            if v < 45 or s < 35:
                continue
            key = (h // 24, s // 72, v // 72)
            b = buckets.setdefault(key, [0, 0, 0, 0])
            b[0] += c.red(); b[1] += c.green(); b[2] += c.blue(); b[3] += 1
    out: list[QColor] = []
    for r, g, bl, n in sorted(buckets.values(), key=lambda b: -b[3]):
        if len(out) >= want:
            break
        h, s, v, _ = QColor(r // n, g // n, bl // n).getHsv()
        if any(min(abs(h - o.hue()), 360 - abs(h - o.hue())) < 18 for o in out):
            continue
        out.append(QColor.fromHsv(h, min(255, int(s * 1.35)), max(70, min(205, v))))
    if not out:
        one = img.scaled(1, 1, Qt.AspectRatioMode.IgnoreAspectRatio,
                         Qt.TransformationMode.SmoothTransformation)
        c = QColor(one.pixel(0, 0))
        h, s, v, _ = c.getHsv()
        out = [QColor.fromHsv(h, min(255, int(s * 1.25)), max(60, min(135, v)))]
    return out


def blurred_cover(img: QImage) -> QImage:
    """A cover as the wall is drawn from it: shrunk to 40px and grown back up
    through four doublings, which is a soft blur for next to nothing."""
    out = img.scaled(40, 40, Qt.AspectRatioMode.KeepAspectRatioByExpanding,
                     Qt.TransformationMode.SmoothTransformation)
    for _ in range(4):
        out = out.scaled(out.width() * 2, out.height() * 2,
                         Qt.AspectRatioMode.IgnoreAspectRatio,
                         Qt.TransformationMode.SmoothTransformation)
    return out


def light_mask(img: QImage) -> QImage:
    """Where the cover is lit, as a 64px alpha: 0 on black, whole from
    BLACK_KNEE up. True black keeps the accent wash off the cover's blacks."""
    g = img.scaled(64, 64, Qt.AspectRatioMode.IgnoreAspectRatio,
                   Qt.TransformationMode.SmoothTransformation
                   ).convertToFormat(QImage.Format.Format_Grayscale8)
    lut = bytes(min(255, round(v / BLACK_KNEE)) for v in range(256))
    raw = bytes(g.constBits().asarray(g.sizeInBytes())).translate(lut)
    return QImage(raw, g.width(), g.height(), g.bytesPerLine(),
                  QImage.Format.Format_Alpha8).copy()


def cover_look(img: QImage) -> tuple:
    """(blurred, palette, brightness): everything the wall takes from a cover.

    QImage only, so it can be worked out on the thread that loaded the
    picture -- see ArtCache for why a QPixmap may not be.
    """
    return blurred_cover(img), palette_of(img), luma_of(img)


def parse_colour(spec: str, fallback: QColor) -> QColor | None:
    """None means 'derive it from the album palette at paint time'."""
    if not spec or spec == "auto":
        return None
    c = QColor(spec)
    return c if c.isValid() else fallback


PIX_BUDGET = 96 << 20
GLOW_BUDGET = 16 << 20

PIX_PER_FRAME = 2
NEW_PER_FRAME = 2
SHAPE_MEMO = 4096


def _pm_bytes(pm: QPixmap) -> int:
    """Roughly what a pixmap costs to keep. Qt does not promise 32 bits per
    pixel, but every format this draws into is, and being out by a channel
    would move a budget, not break one."""
    return max(1, pm.width() * pm.height() * 4)


_DWMWA_CORNER = 33
_DWMWA_BORDER = 34
_DWMWCP_DEFAULT, _DWMWCP_DONOTROUND = 0, 1
_DWMWA_COLOR_NONE, _DWMWA_COLOR_DEFAULT = 0xFFFFFFFE, 0xFFFFFFFF
_DWMWA_DARK = 20
_DWMWA_BACKDROP = 38
_DWM_BACKDROP = {"none": 1, "mica": 2, "acrylic": 3, "tabbed": 4}


def _dwm_backdrop(wid: int, kind: str) -> bool:
    """Put a Windows 11 material (DWMWA_SYSTEMBACKDROP_TYPE, 22H2+) behind our
    window, in dark mode. True if it took."""
    if os.name != "nt" or kind not in _DWM_BACKDROP:
        return False
    try:
        import ctypes
        dwm = ctypes.windll.dwmapi                   # noqa: F821
        hwnd = ctypes.c_void_p(int(wid))
        dark = ctypes.c_int(1)
        dwm.DwmSetWindowAttribute(hwnd, ctypes.c_uint(_DWMWA_DARK),
                                  ctypes.byref(dark), ctypes.sizeof(dark))
        if kind != "none" and _layered(hwnd):
            # DWM takes the attribute and draws nothing behind a layered
            # window, which is what Qt makes a clear one: the drawer said
            # "mica" over plain glass (docs/notes lyrics_gui.md, 2026-10-17).
            return False
        val = ctypes.c_int(_DWM_BACKDROP[kind])
        hr = dwm.DwmSetWindowAttribute(hwnd, ctypes.c_uint(_DWMWA_BACKDROP),
                                       ctypes.byref(val), ctypes.sizeof(val))
        if hr == 0 and kind != "none":
            class Margins(ctypes.Structure):
                _fields_ = [("left", ctypes.c_int), ("right", ctypes.c_int),
                            ("top", ctypes.c_int), ("bottom", ctypes.c_int)]
            dwm.DwmExtendFrameIntoClientArea(hwnd, ctypes.byref(Margins(-1, -1, -1, -1)))
        return hr == 0
    except Exception:
        return False


_KWE = None        # KF6's KWindowEffects, (available, blur, contrast) -- False if unusable

# KWin has one blur, so the three materials are told apart on KDE the way
# Windows tells them apart: a tint of our own over the blur, and KWin's
# background contrast (contrast, brightness, saturation) where it is on.
# Acrylic is the blur alone, mica more solid and muted, tabbed darker still.
KDE_MATERIAL = {
    "acrylic": (None, None),
    "mica": ((24, 24, 28, 0.30), (0.9, 0.8, 0.6)),
    "tabbed": ((14, 14, 18, 0.45), (0.85, 0.6, 0.5)),
}


def _kwin_effects():
    """KF6 KWindowSystem's KWindowEffects, called through ctypes, or None.

    Only where KF6 sits beside the Qt this process already runs on: PyQt
    on the system's Qt (a distribution's package). A pip PyQt brings its own
    Qt, and loading KF6 would put a second one in the process, so there it
    is never loaded at all."""
    global _KWE
    if _KWE is not None:
        return _KWE or None
    _KWE = False
    if not sys.platform.startswith("linux"):
        return None
    try:
        import ctypes
        core = next((ln.split()[-1] for ln in open("/proc/self/maps")
                     if "/libQt6Core.so" in ln), None)
        if core is None:
            return None
        lib = os.path.join(os.path.dirname(core), "libKF6WindowSystem.so.6")
        if not os.path.exists(lib):
            return None
        kwe = ctypes.CDLL(lib)
        avail = kwe["_ZN14KWindowEffects17isEffectAvailableENS_6EffectE"]
        avail.argtypes, avail.restype = [ctypes.c_int], ctypes.c_bool
        blur = kwe["_ZN14KWindowEffects16enableBlurBehindEP7QWindowbRK7QRegion"]
        blur.argtypes = [ctypes.c_void_p, ctypes.c_bool, ctypes.c_void_p]
        blur.restype = None
        con = kwe["_ZN14KWindowEffects24enableBackgroundContrastEP7QWindowbdddRK7QRegion"]
        con.argtypes = [ctypes.c_void_p, ctypes.c_bool, ctypes.c_double,
                        ctypes.c_double, ctypes.c_double, ctypes.c_void_p]
        con.restype = None
        _KWE = (avail, blur, con)
    except Exception:                                    # noqa: BLE001
        _KWE = False
    return _KWE or None


def _kwin_blur(window, on: bool, contrast=None) -> bool:
    """Ask KWin to blur what is behind a clear window (its Blur effect, the
    nearest thing KDE has to Windows' materials), with `contrast`
    (contrast, brightness, saturation) where KWin has that effect on. True
    if the blur was asked for and is there; never loads KF6 to turn it off."""
    if not on and _KWE is None:
        return False
    kwe = _kwin_effects()
    if kwe is None or window is None:
        return False
    avail, blur, con = kwe
    try:
        from PyQt6 import sip
        # Asked whatever availability says: on Wayland it reads False until
        # KWin's globals arrive (one roundtrip, measured 2026-10-17), and KF6
        # keeps the request and applies it then. apply_backdrop asks again.
        region = QRegion()                               # empty: the whole window
        win, reg = sip.unwrapinstance(window), sip.unwrapinstance(region)
        blur(win, bool(on), reg)
        c, i, sat = contrast or (1.0, 1.0, 1.0)
        con(win, bool(on and contrast), c, i, sat, reg)
        return on and avail(7)                           # KWindowEffects::BlurBehind
    except Exception:                                    # noqa: BLE001
        return False


WIN_MATERIALS = ("mica", "acrylic", "tabbed")


def _no_client_frame(message, hwnd: int) -> bool:
    """WM_NCCALCSIZE answered "all of it is client area", for a window kept
    framed so Qt does not make it layered (see LyricsView.win_material):
    the title bar and borders go, the frame DWM puts its material on stays.
    Maximised, the window is inset by its frame, which Windows otherwise
    hangs off the screen. True if this message was that one, for `hwnd`."""
    try:
        import ctypes
        from ctypes import wintypes
        msg = wintypes.MSG.from_address(int(message))
        if msg.message != 0x0083 or not msg.wParam:      # WM_NCCALCSIZE, TRUE
            return False
        if (msg.hWnd or 0) != hwnd:
            return False
        user32 = ctypes.windll.user32                    # noqa: F821
        if user32.IsZoomed(msg.hWnd):
            r = wintypes.RECT.from_address(msg.lParam)   # rgrc[0]
            b = user32.GetSystemMetrics(32) + user32.GetSystemMetrics(92)
            r.left += b
            r.top += b
            r.right -= b
            r.bottom -= b
        return True
    except Exception:                                    # noqa: BLE001
        return False


class _FrameFilter(QAbstractNativeEventFilter):
    """_no_client_frame for one window; `hwnd` is set once it is known
    (apply_backdrop), and _frame_changed has Windows ask again then."""

    def __init__(self, view) -> None:
        super().__init__()
        self.view = view
        self.hwnd = 0

    def nativeEventFilter(self, kind, message):           # noqa: N802 (Qt name)
        if (self.hwnd and bytes(kind) == b"windows_generic_MSG"
                and _no_client_frame(message, self.hwnd)):
            return True, 0
        return False, 0


def _frame_changed(wid: int) -> None:
    """Have Windows ask the window for its frame again (SWP_FRAMECHANGED),
    so _no_client_frame is heard for a window made before it could be."""
    try:
        import ctypes
        ctypes.windll.user32.SetWindowPos(               # noqa: F821
            ctypes.c_void_p(int(wid)), None, 0, 0, 0, 0,
            0x0001 | 0x0002 | 0x0004 | 0x0010 | 0x0020)  # NOSIZE MOVE ZORDER ACTIVATE, FRAMECHANGED
    except Exception:                                    # noqa: BLE001
        pass


def _layered(hwnd) -> bool:
    """Whether a window is WS_EX_LAYERED; False where it cannot be told."""
    try:
        import ctypes
        user32 = ctypes.windll.user32                    # noqa: F821
        get = getattr(user32, "GetWindowLongPtrW", None) or user32.GetWindowLongW
        get.restype = ctypes.c_ssize_t
        get.argtypes = [ctypes.c_void_p, ctypes.c_int]
        return bool(get(hwnd, -20) & 0x80000)           # GWL_EXSTYLE, WS_EX_LAYERED
    except Exception:                                    # noqa: BLE001
        return False


def _no_dwm_border(w, rounded: bool = False) -> None:
    """Ask DWM not to round or outline this window. Silent where it cannot."""
    if os.name != "nt":
        return
    try:
        import ctypes
        hwnd = int(w.winId())
        dwm = ctypes.windll.dwmapi                       # noqa: F821
        for attr, value in (
                (_DWMWA_CORNER,
                 _DWMWCP_DEFAULT if rounded else _DWMWCP_DONOTROUND),
                (_DWMWA_BORDER,
                 _DWMWA_COLOR_DEFAULT if rounded else _DWMWA_COLOR_NONE)):
            val = ctypes.c_int(value) if attr == _DWMWA_CORNER else \
                ctypes.c_uint(value)
            dwm.DwmSetWindowAttribute(ctypes.c_void_p(hwnd), ctypes.c_uint(attr),
                                      ctypes.byref(val), ctypes.sizeof(val))
    except Exception:                                    # noqa: BLE001
        pass


def soft_scale(pm: QPixmap, factor: float, keep_half: bool = False) -> QPixmap:
    """Blur a pixmap by halving and doubling it through a mip chain."""
    w, h = pm.width(), pm.height()
    tw, th = max(1, int(w / factor)), max(1, int(h / factor))
    ig, sm = Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation
    small = pm
    while small.width() // 2 > tw and small.height() // 2 > th:
        small = small.scaled(small.width() // 2, small.height() // 2, ig, sm)
    small = small.scaled(tw, th, ig, sm)
    while small.width() * 2 < w and small.height() * 2 < h:
        small = small.scaled(small.width() * 2, small.height() * 2, ig, sm)
    if keep_half and abs(small.width() * 2 - w) <= 1 and abs(small.height() * 2 - h) <= 1:
        # the last step is an exact 2x, which drawing it does just the same
        # (memory minimal; docs/notes memory_mode.md)
        small.setDevicePixelRatio(small.width() / w)
        return small
    return small.scaled(w, h, ig, sm)


def advance(fm: QFontMetricsF, txt: str) -> float:
    """fm.horizontalAdvance, memoised on the QFontMetricsF so it survives
    layout cache flushes and dies with the face."""
    try:
        memo = fm._adv
    except AttributeError:
        memo = fm._adv = {}
    got = memo.get(txt)
    if got is None:
        if len(memo) > 8192:
            memo.clear()
        got = memo[txt] = fm.horizontalAdvance(txt)
    return got


_METRICS: dict = {}


def face_metrics(font: QFont) -> QFontMetricsF:
    """QFontMetricsF for `font`, one per face, so the advance and wrap_shape
    memos hung on it outlive a layout (the ruby and romaji rows made a new
    one every time)."""
    key = RD.font_key(font)
    fm = _METRICS.get(key)
    if fm is None:
        if len(_METRICS) > 64:
            _METRICS.clear()
        fm = _METRICS[key] = QFontMetricsF(font)
    return fm


def split_to_fit(piece: tuple, fm: QFontMetricsF, width: float) -> list[tuple]:
    """Break one timed fragment into chunks that each fit the column.

    Japanese and Chinese lines carry no spaces, so the whole line arrives as a
    single unbreakable token and used to run straight off the right edge. Split
    it per character and interpolate the timings across the pieces.
    """
    s, e, txt, part = piece
    if len(txt) < 2 or advance(fm, txt) <= width:
        return [piece]
    chunks, cur = [], ""
    for ch in txt:
        if cur and advance(fm, cur + ch) > width:
            chunks.append(cur)
            cur = ch
        else:
            cur += ch
    if cur:
        chunks.append(cur)
    if len(chunks) < 2:
        return [piece]
    timed = isinstance(s, (int, float)) and isinstance(e, (int, float)) and e > s
    out, t, total = [], s, len(txt)
    for i, c in enumerate(chunks):
        last = i == len(chunks) - 1
        end = e if last or not timed else t + (e - s) * len(c) / total
        out.append((t, end, c, part if last else True))
        t = end
    return out


NO_LEAD = set(",.!?;:)]}\u2019\u201d\u3001\u3002\uff0c\uff0e\uff01\uff1f"
              "\uff1b\uff1a\uff09\u300d\u300f\u3011\u3009\u300b")


def _leads_badly(word) -> bool:
    txt = "".join(pc[2] for _i, _c, pc in word).lstrip()
    return bool(txt) and txt[0] in NO_LEAD


SPACED_MARKS = set("?!:;")


def _glues_back(word) -> bool:
    """Whether a word is drawn against the one before without a space: only a
    word that is nothing but marks (not ? ! : ;)."""
    txt = "".join(pc[2] for _i, _c, pc in word).strip()
    return (_leads_badly(word) and txt[0] not in SPACED_MARKS
            and not any(c.isalnum() for c in txt))


def wrap_shape(pieces, fm: QFontMetricsF, width: float, align: str):
    """Where the words go, with no clock: rows of (x, advance, text, piece,
    chunk) plus split piece lengths, memoised on the font metrics."""
    try:
        memo = fm._shape
    except AttributeError:
        memo = fm._shape = {}
    key = (tuple((pc[2], bool(pc[3])) for pc in pieces), int(width), align)
    got = memo.get(key)
    if got is not None:
        return got

    words: list[list] = []
    cur: list = []
    for i, pc in enumerate(pieces):
        cur.append((i, 0, pc))
        if not pc[3]:
            words.append(cur)
            cur = []
    if cur:
        words.append(cur)

    chunks: dict = {}
    rows: list[list] = [[]]
    x = 0.0
    last_word = len(words) - 1
    glued = [wi + 1 < len(words) and _glues_back(words[wi + 1])
             for wi in range(len(words))]
    prev_at = None
    for wi, word in enumerate(words):
        adv = [advance(fm, pc[2]) for _i, _c, pc in word]
        core = sum(adv)
        atomic = True
        if core > width:
            grown = []
            for i, _c, pc in word:
                subs = split_to_fit(pc, fm, width)
                if len(subs) > 1:
                    chunks[i] = [len(sub[2]) for sub in subs]
                grown += [(i, ci, sub) for ci, sub in enumerate(subs)]
            word = grown
            adv = None
            atomic = False
        elif x + core > width and rows[-1]:
            carry = []
            if (_leads_badly(word) and prev_at is not None
                    and prev_at[0] == len(rows) - 1 and prev_at[1] > 0):
                carry = rows[-1][prev_at[1]:]
                del rows[-1][prev_at[1]:]
            rows.append([])
            x = 0.0
            for _x, w, t, i, ci in carry:
                rows[-1].append((x, w, t, i, ci))
                x += w
        prev_at = (len(rows) - 1, len(rows[-1]))
        last_piece = len(word) - 1
        for j, (i, ci, (s, e, txt, part)) in enumerate(word):
            if j == last_piece and wi < last_word and not glued[wi]:
                txt += " "
                w = advance(fm, txt)
            elif adv is not None:
                w = adv[j]
            else:
                w = advance(fm, txt)
            if not atomic and x + w > width and rows[-1]:
                rows.append([])
                x = 0.0
            rows[-1].append((x, w, txt, i, ci))
            x += w
    if LANG.is_rtl("".join(pc[2] for pc in pieces)):
        rows = [rtl_row(row, fm, width, align) for row in rows]
    elif align != "left":
        for row in rows:
            if not row:
                continue
            rw = row[-1][0] + advance(fm, row[-1][2].rstrip())
            slack = max(0.0, width - rw)
            dx = slack if align == "right" else slack / 2
            row[:] = [(x + dx, w, t, i, ci) for x, w, t, i, ci in row]
    if len(memo) > SHAPE_MEMO:
        memo.clear()
    memo[key] = (rows, chunks)
    return rows, chunks


def rtl_row(row, fm: QFontMetricsF, width: float, align: str) -> list:
    """A row turned round for a right-to-left line: leading spaces, ZWJ at
    Arabic joins, LTR runs kept in order; alignment mirrored."""
    ents = [list(en) for en in row]
    for a, b in zip(ents, ents[1:]):
        if not a[2].endswith(" ") and LANG.joins(a[2], b[2]):
            a[2] += LANG.ZWJ
            b[2] = LANG.ZWJ + b[2]
    words, cur = [], []
    for en in ents:
        txt = en[2]
        if txt.endswith(" "):
            en[2] = " \u200e" + txt[:-1]
        cur.append(en)
        if txt.endswith(" "):
            words.append(cur)
            cur = []
    if cur:
        words.append(cur)
    ltr = [LANG.strong_ltr("".join(en[2] for en in wd)) for wd in words]
    segs, k = [], 0
    while k < len(words):
        if ltr[k]:
            end = k
            for j in range(k + 1, len(words)):
                if ltr[j]:
                    end = j
                elif LANG.is_rtl("".join(en[2] for en in words[j])):
                    break
            segs.append([en for wd in words[k:end + 1] for en in wd])
            k = end + 1
        else:
            segs.append(list(reversed(words[k])))
            k += 1
    out, x = [], 0.0
    for seg in reversed(segs):
        for _x, _w, txt, i, ci in seg:
            w = advance(fm, txt)
            out.append((x, w, txt, i, ci))
            x += w
    if not out:
        return out
    lead = out[0][1] - advance(fm, out[0][2].lstrip())
    ink = x - lead
    if align == "right":
        dx = -lead
    elif align == "centre":
        dx = max(0.0, width - ink) / 2 - lead
    else:
        dx = max(-lead, width - x)
    return sorted(((x + dx, w, t, i, ci) for x, w, t, i, ci in out),
                  key=lambda en: (en[3], en[4]))


def stamp_rows(shape, pieces):
    """A shape, with this document's times written onto it.

    The arithmetic for a split piece is split_to_fit's own, character by
    character, and the untimed case falls out the same way it does there: the
    first chunk carries the whole span and the rest are empty at the end of it.
    """
    rows, chunks = shape
    times: dict = {}
    for i, lens in chunks.items():
        s, e, txt, _part = pieces[i]
        timed = (isinstance(s, (int, float)) and isinstance(e, (int, float))
                 and e > s)
        total = sum(lens)
        out, t = [], s
        for ci, n in enumerate(lens):
            last = ci == len(lens) - 1
            end = e if last or not timed else t + (e - s) * n / total
            out.append((t, end))
            t = end
        times[i] = out
    out_rows = []
    for row in rows:
        line = []
        for x, w, txt, i, ci in row:
            got = times.get(i)
            if got is None:
                s, e = pieces[i][0], pieces[i][1]
            else:
                s, e = got[ci]
            line.append((x, w, txt, s, e))
        out_rows.append(line)
    return out_rows


def SL_norm(t: str) -> str:
    return re.sub(r"[^0-9a-z\u3040-\u30ff\u4e00-\u9fff]", "", (t or "").lower())


def track_id(meta) -> str | None:
    found = re.search(r"([A-Za-z0-9]{22})", str((meta or {}).get("mpris:trackid", "")))
    return found.group(1) if found else None


def _read_config() -> dict:
    """Settings, falling back to the previous generation if the live file is
    gone or unreadable."""
    for path in (CONFIG, CONFIG.with_suffix(".json.bak")):
        try:
            got = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(got, dict):
                return british(got)
        except Exception:
            continue
    return {}


HAND_FIX_MAX = 3


def load_romaji() -> dict:
    """Per-track romaji corrections keyed by the original line text; old
    whole-song Genius alignments found here are dropped."""
    got = _read_config().get("romaji") or {}
    return {t: dict(v) for t, v in got.items()
            if isinstance(v, dict) and len(v) <= HAND_FIX_MAX}


def load_genius() -> tuple[dict, dict]:
    """Cached Genius alignments with the matcher revision each was made by;
    older revisions are dropped and re-fetched."""
    cfg = _read_config()
    got = cfg.get("genius") or {}
    revs = cfg.get("genius_rev") or {}
    out, keep = {}, {}
    for t, v in got.items():
        if not isinstance(v, dict):
            continue
        try:
            rev = int(revs.get(t, 0))
        except Exception:
            rev = 0
        if rev == GR.REVISION:
            out[t], keep[t] = dict(v), rev
    return out, keep


def load_token() -> str:
    """The Genius token lives in the settings file but never on the command
    line, where it would sit in shell history and the process list."""
    return str(_read_config().get("genius_token") or "")


def load_offsets() -> dict:
    """Per-track corrections, adding back the `lag` an earlier version
    subtracted from them; one-shot and idempotent."""
    cfg = _read_config()
    try:
        got = {k: float(v) for k, v in (cfg.get("offsets") or {}).items()}
    except Exception:
        return {}
    try:
        lag = float(cfg.get("lag") or 0.0)
    except Exception:
        lag = 0.0
    return {k: round(v + lag, 3) for k, v in got.items()} if lag else got


_SINKS: dict[int, tuple[str, str]] = {}


def _pactl(*argv: str) -> str:
    out = subprocess.run(("pactl",) + argv, capture_output=True, text=True,
                         timeout=2.0)
    return out.stdout if out.returncode == 0 else ""


def _sinks() -> None:
    """Index -> (id, name) for every output, re-read only when an unknown index
    turns up."""
    try:
        rows = json.loads(_pactl("-f", "json", "list", "sinks") or "[]")
    except Exception:                                       # noqa: BLE001
        return
    _SINKS.clear()
    for row in rows if isinstance(rows, list) else []:
        name = str((row or {}).get("name") or "")
        if name:
            _SINKS[row.get("index")] = (name, str(row.get("description") or "")
                                        or name)


def audio_sink(app: str = DEVICE_APP) -> tuple[str, str]:
    """Where the song's sound comes out, (id, name): the player app's own
    stream on Linux, the default output on macOS and Windows; ("", "") if
    unknown."""
    if sys.platform == "darwin":
        return MP.default_output()
    if os.name == "nt":
        return windows_output()
    if not sys.platform.startswith("linux"):
        return "", ""
    try:
        rows = json.loads(_pactl("-f", "json", "list", "sink-inputs") or "[]")
        at = None
        for row in rows if isinstance(rows, list) else []:
            props = (row or {}).get("properties") or {}
            who = " ".join(str(props.get(k) or "") for k in
                           ("application.name", "application.process.binary"))
            if app in who.lower():
                at = row.get("sink")
                break
        if at is None:
            name = (_pactl("get-default-sink") or "").strip()
            if not name:
                return "", ""
            if name not in {n for n, _ in _SINKS.values()}:
                _sinks()
            return name, dict(_SINKS.values()).get(name, name)
        if at not in _SINKS:
            _sinks()
        return _SINKS.get(at, ("", ""))
    except Exception:                                       # noqa: BLE001
        return "", ""


_WIN_OUT: tuple = ("", "", 0.0)

WIN_GUID = re.compile(r"\{[0-9a-fA-F]{8}-(?:[0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12}\}")

WIN_NAMED = ("{a45c254e-df1c-4efd-8020-67d146a850e0},2",
             "{b3f8fa53-0004-438e-9003-51a46e139bfc},6",
             "{a45c254e-df1c-4efd-8020-67d146a850e0},14")


WINRT_NAMESPACES = ("windows.media.control", "windows.foundation",
               "windows.foundation.collections", "windows.storage.streams")
WINRT_FIX = ("Windows' media transport needs these winrt namespaces: "
             "pip install winrt-runtime winrt-Windows.Foundation "
             "winrt-Windows.Foundation.Collections winrt-Windows.Media "
             "winrt-Windows.Media.Control winrt-Windows.Storage.Streams "
             "winrt-Windows.Media.Devices winrt-Windows.Devices.Enumeration")


@functools.lru_cache(maxsize=1)
def winrt_projection() -> str:
    """"winsdk", "winrt" or "": the projection that answers for every
    namespace, cached."""
    import importlib

    for pkg in ("winsdk", "winrt"):
        try:
            for tail in WINRT_NAMESPACES:
                importlib.import_module(f"{pkg}.{tail}")
            return pkg
        except ImportError:
            continue
    return ""


WINRT_WAIT = 3.0       # longest any WinRT operation is waited for
THUMB_WAIT = 0.75      # a cover read's two steps, each (no cover rather than a late one)
_WINRT_KEPT: list = []  # objects of operations that never finished: never freed (see _WinrtHome)


async def _await_winrt_operation(operation):
    """Await a WinRT operation when the projection has no synchronous get()."""
    return await operation


def _run_winrt_here(call, *args, timeout: float = WINRT_WAIT):
    """Create and finish a WinRT async operation on the current thread, for at most
    `timeout`. One that runs over is cancelled, kept for good and raised as TimeoutError."""
    operation = call(*args)
    wait = getattr(operation, "wait", None)
    if callable(wait):
        status = wait(timeout)
        if int(getattr(status, "value", status)) != 0:          # 0 = AsyncStatus.STARTED
            return operation.get()
    else:
        import asyncio
        try:
            return asyncio.run(asyncio.wait_for(_await_winrt_operation(operation), timeout))
        except asyncio.TimeoutError:
            pass
    try:
        operation.cancel()
    except Exception:                                       # noqa: BLE001
        pass
    _WINRT_KEPT.append(operation)
    raise TimeoutError("Windows' media service did not answer")


class _WinrtHome:
    """The one thread every WinRT call is made on and every WinRT object is freed on.
    See docs/notes/mild-lyrics/lyrics_gui.md, 2026-10-22 "Windows freeze at startup"."""

    def __init__(self) -> None:
        self._jobs: queue.Queue = queue.Queue()
        self._thread: threading.Thread | None = None
        self._since = 0.0                   # when the running job began; 0 while idle
        self._lock = threading.Lock()

    def here(self) -> bool:
        return threading.current_thread() is self._thread

    def call(self, fn, *args, timeout: float = WINRT_WAIT):
        """fn(*args) on the WinRT thread. Only plain values should come back out."""
        if self.here():
            return fn(*args)
        with self._lock:
            if self._thread is None:
                self._thread = threading.Thread(target=self._run, name="mild-winrt", daemon=True)
                self._thread.start()
            if self._since and mono() - self._since > timeout:
                raise TimeoutError("Windows' media service is not answering")
        box: dict = {}
        done = threading.Event()
        self._jobs.put((fn, args, box, done))
        if not done.wait(timeout):
            raise TimeoutError("Windows' media service did not answer")
        if "error" in box:
            raise box.pop("error")
        return box.pop("value", None)

    def _run(self) -> None:
        while True:
            job = self._jobs.get()
            fn, args, box, done = job
            self._since = mono()
            try:
                box["value"] = fn(*args)
            except BaseException as exc:            # noqa: BLE001
                # The traceback's frames hold WinRT locals: free them here, not on the caller.
                exc.__traceback__ = exc.__context__ = exc.__cause__ = None
                box["error"] = exc
            finally:
                self._since = 0.0
                done.set()
            del job, fn, args, box, done


_WINRT = _WinrtHome()


def _run_async_call(call, *args):
    """A WinRT operation's result, made on the WinRT thread (see _WinrtHome)."""
    if _WINRT.here():
        return _run_winrt_here(call, *args)
    return _WINRT.call(_run_winrt_here, call, *args)


def _win_reg_name(dev: str) -> str:
    """An output's friendly name read off the registry, when the device lookup
    will not answer."""
    found = WIN_GUID.search(dev or "")
    if not found:
        return ""
    try:
        import winreg

        path = (r"SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio"
                "\\Render\\" + found.group(0) + r"\Properties")
        with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, path) as key:
            for prop in WIN_NAMED:
                try:
                    got = winreg.QueryValueEx(key, prop)[0]
                except OSError:
                    continue
                if isinstance(got, str) and got.strip():
                    return got.strip()
    except Exception:                                       # noqa: BLE001
        return ""
    return ""


def _win_short(dev: str) -> str:
    """A short label for an output with no name: the endpoint guid's first
    block."""
    found = WIN_GUID.search(dev or "")
    return f"Windows output ({found.group(0)[1:9]})" if found else "Windows output"


def windows_output() -> tuple[str, str]:
    """_windows_output, on the WinRT thread; ("", "") when it does not answer."""
    try:
        return _WINRT.call(_windows_output)
    except Exception:                                       # noqa: BLE001
        return "", ""


def _windows_output() -> tuple[str, str]:
    """Windows' current output as (interface path, name), the name cached a few
    seconds against the id."""
    global _WIN_OUT
    try:
        try:
            from winsdk.windows.media.devices import MediaDevice
        except ImportError:
            from winrt.windows.media.devices import MediaDevice
        dev = MediaDevice.get_default_audio_render_id(0)
        if not dev:
            return "", ""
        if _WIN_OUT[0] == dev:
            return _WIN_OUT[0], _WIN_OUT[1]
        name = ""
        try:
            try:
                from winsdk.windows.devices.enumeration import DeviceInformation
            except ImportError:
                from winrt.windows.devices.enumeration import DeviceInformation
            info = _run_async_call(DeviceInformation.create_from_id_async, dev)
            name = (getattr(info, "name", "") or "").strip()
        except Exception:                                   # noqa: BLE001
            name = ""
        name = name or _win_reg_name(dev) or _win_short(dev)
        _WIN_OUT = (dev, name, mono())
        return dev, name
    except Exception:                                       # noqa: BLE001
        return "", ""


def load_est() -> dict:
    """Measured timing offsets, dropped when made by an older estimator
    revision; hand corrections untouched."""
    out = {}
    for tid, got in (_read_config().get("est") or {}).items():
        try:
            if isinstance(got, dict) and got.get("own"):        # heard from our own player's audio
                if int(got.get("rev", 0)) == AA.OFFSET_REV:
                    out[tid] = {k: got[k] for k in ("delta", "ratio", "adv", "spread", "n", "sure",
                                                    "fit", "own", "rev", "cleared") if k in got}
                continue
            if isinstance(got, dict) and int(got.get("rev", 0)) == EST_REVISION:
                out[tid] = {"delta": float(got["delta"]), "conf": float(got["conf"]),
                            "spread": float(got.get("spread", EST_RANGE * 2.0)),
                            "n": int(got.get("n", 0)), "rev": EST_REVISION}
                if got.get("cleared"):
                    out[tid]["cleared"] = True
        except Exception:
            continue
    return out


def load_settings() -> dict:
    got = _fps_cap(_merge_ms(_upgrade_sources(_read_config())))
    if "duet_colour" in got:
        got = dict(got, duet_colour=_duet_mode(got["duet_colour"]))
    if got.get("src_order"):
        got = dict(got, src_order=",".join(LS.lrclib_first(LS.carried(
            [n.strip() for n in str(got["src_order"]).split(",")]))))
    return {k: got[k] for k in DEFAULTS if k in got}


def _duet_mode(v):
    """'off' was the duet colour's name for white before it was spelled the
    way the sung colour spells it; a saved or typed 'off' still means that."""
    return "white" if str(v or "").strip().casefold() in ("", "off") else v


def _fps_cap(got: dict) -> dict:
    """Carry a pre-setting fps cap over: an unmarked 0 becomes FPS_CAP_DEFAULT,
    anything typed stays (`fps_cap_set`)."""
    if not isinstance(got, dict) or got.get("fps_cap_set") or "fps_cap" not in got:
        return got
    try:
        was = float(got["fps_cap"])
    except (TypeError, ValueError):
        was = 0.0
    return dict(got, fps_cap=was if was > 0 else FPS_CAP_DEFAULT)


MERGE_WAS_ON = 40.0


def _merge_ms(got: dict) -> dict:
    """Carry the old fractional merge setting over as on (MERGE_WAS_ON) or off."""
    if not isinstance(got, dict) or "merge_ms" in got or "merge_splits" not in got:
        return got
    try:
        was = float(got.get("merge_splits") or 0.0)
    except (TypeError, ValueError):
        was = 0.0
    return dict(got, merge_ms=MERGE_WAS_ON if was > 0 else 0.0)


def _upgrade_sources(got: dict) -> dict:
    """Upgrade a provider-list settings file: switches carried by source, the
    order reset to default; old blend switches deliberately not carried."""
    if not isinstance(got, dict) or "src_apple" in got:
        return got
    if not any(k.startswith("src_") for k in got):
        return got
    got = dict(got)
    for name, attr in SRC_ATTR.items():
        if attr in got:
            continue
        was = [old for old, now in WAS_SRC.items() if now == name] or [name]
        marks = [bool(got[f"src_{old}"]) for old in was if f"src_{old}" in got]
        got[attr] = any(marks) if marks else DEFAULTS[attr]
    if any(n in WAS_SRC for n in str(got.get("src_order") or "").split(",")):
        got["src_order"] = ",".join(SRC_DEFAULT)
    return got


def save_settings(values: dict, offsets: dict | None = None,
                  romaji: dict | None = None, token: str | None = None,
                  genius: dict | None = None, genius_rev: dict | None = None,
                  est: dict | None = None) -> None:
    try:
        CONFIG.parent.mkdir(parents=True, exist_ok=True)
        if offsets is not None:
            values = dict(values, offsets={k: float(v) for k, v in offsets.items()
                                           if v is not None})
        if est is not None:
            values = dict(values, est=est)
        if romaji is not None:
            values = dict(values, romaji={k: v for k, v in romaji.items() if v})
        if genius is not None:
            values = dict(values, genius={k: v for k, v in genius.items() if v})
        if genius_rev is not None:
            values = dict(values, genius_rev=dict(genius_rev))
        if token is not None:
            values = dict(values, genius_token=token)
        if CONFIG.exists():
            try:
                CONFIG.replace(CONFIG.with_suffix(".json.bak"))
            except Exception:
                pass
        CONFIG.write_text(json.dumps(values, indent=2), encoding="utf-8")
    except Exception:
        pass


_kwin_seq = 0


def kwin_keep_above(title: str, on: bool) -> bool:
    """Ask KWin over D-Bus to keep our window above the rest (Wayland ignores
    the hint). True if it took."""
    global _kwin_seq
    try:
        import dbus
    except ImportError:
        return False
    js = """
var list = (workspace.windowList ? workspace.windowList() : workspace.clientList());
for (var i = 0; i < list.length; i++) {
    if (String(list[i].caption || "") === %s) list[i].keepAbove = %s;
}
""" % (json.dumps(title), "true" if on else "false")
    try:
        path = pathlib.Path(tempfile.gettempdir()) / f"spicy-keepabove-{os.getpid()}.js"
        path.write_text(js, encoding="utf-8")
        bus = dbus.SessionBus()
        obj = bus.get_object("org.kde.KWin", "/Scripting")
        iface = dbus.Interface(obj, "org.kde.kwin.Scripting")
        _kwin_seq += 1
        iface.loadScript(str(path), f"spicy-keepabove-{os.getpid()}-{_kwin_seq}",
                         signature="ss")
        iface.start()
        return True
    except Exception:
        return False


def x11_composited() -> bool:
    """Whether a compositing manager owns _NET_WM_CM_S0 on this X display,
    asked afresh; False when the display cannot be opened."""
    try:
        import ctypes
        import ctypes.util
        lib = ctypes.util.find_library("X11")
        if not lib:
            return False
        x11 = ctypes.CDLL(lib)
        x11.XOpenDisplay.restype = ctypes.c_void_p
        x11.XOpenDisplay.argtypes = [ctypes.c_char_p]
        x11.XInternAtom.restype = ctypes.c_ulong
        x11.XInternAtom.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_int]
        x11.XGetSelectionOwner.restype = ctypes.c_ulong
        x11.XGetSelectionOwner.argtypes = [ctypes.c_void_p, ctypes.c_ulong]
        x11.XCloseDisplay.argtypes = [ctypes.c_void_p]
        dpy = x11.XOpenDisplay(None)
        if not dpy:
            return False
        try:
            atom = x11.XInternAtom(dpy, b"_NET_WM_CM_S0", 0)
            return bool(atom) and bool(x11.XGetSelectionOwner(dpy, atom))
        finally:
            x11.XCloseDisplay(dpy)
    except Exception:
        return False


def clear_ok() -> bool:
    """Whether a see-through window will actually be see-through here."""
    plat = QApplication.platformName() or ""
    if plat.startswith("wayland") or os.name == "nt" or sys.platform == "darwin":
        return True
    if plat.startswith("xcb"):
        return x11_composited()
    return True


def _smooth(t: float) -> float:
    """Ease in and out, so a cloud leaves and arrives without a visible
    start or stop -- a linear ramp reads as a slide, a cubic as a snap."""
    t = max(0.0, min(1.0, t))
    return t * t * (3.0 - 2.0 * t)


RD.TEXT, RD._smooth, RD.soft_scale = TEXT, _smooth, soft_scale


def fmt_time(sec: float) -> str:
    sec = max(0, int(sec))
    return f"{sec // 60}:{sec % 60:02d}"


def wrap_parts(fm: QFontMetricsF, parts, sep: str, width: float,
               maxrows: int = 3) -> list:
    """Wrap a line that is a row of parts, keeping the parts apart; the last
    row may run long rather than elide."""
    rows, cur = [], ""
    for part in parts:
        joined = f"{cur}{sep}{part}" if cur else part
        if cur and fm.horizontalAdvance(joined) > width \
                and len(rows) + 1 < maxrows:
            rows.append(cur)
            cur = part
        else:
            cur = joined
    if cur:
        rows.append(cur)
    return rows or [""]


# Settings saved under an American spelling before they were renamed: the
# key it was kept under, and values that were written the old way. Read
# wherever settings come in -- the settings file, presets, shared text and
# the command line -- so nothing kept from before is lost.
OLD_KEYS = {"sung_color": "sung_colour", "duet_color": "duet_colour",
            "mesh_colors": "mesh_colours"}
OLD_VALUES = {"center": "centre"}


def british(vals: dict) -> dict:
    """Settings with any old American key or value moved to its new name.

    A key already under its new name wins over its old one."""
    out = {}
    for k, v in vals.items():
        if k in OLD_KEYS:
            if OLD_KEYS[k] in vals:
                continue
            k = OLD_KEYS[k]
        if isinstance(v, str):
            v = OLD_VALUES.get(v, v)
        elif isinstance(v, dict) and k == "presets":
            v = {n: british(p) if isinstance(p, dict) else p
                 for n, p in v.items()}
        out[k] = v
    return out


# Labels shared settings were written with before a row was renamed, so text
# copied out of an older build still reads.
SHARE_OLD_LABELS = {
    "sync makers' faces": "Sync makers' profile pictures",
    "visualizer": "Visualiser",
    "visualizer mode": "Visualiser mode",
}


def wrap_rows(fm: QFontMetricsF, text: str, width: float, maxrows: int = 2,
              elide: bool = True) -> list[str]:
    """Greedy word wrap. Overflow piles onto the last row, which is then elided.

    `elide=False` leaves that row over-long on purpose, for a caller that would
    rather scroll it than cut it. A still image has no such option, so the share
    card keeps the ellipsis.
    """
    rows, cur = [], ""
    for w in text.split():
        joined = f"{cur} {w}".strip()
        if cur and advance(fm, joined) > width:
            if len(rows) + 1 == maxrows:
                cur = joined
            else:
                rows.append(cur)
                cur = w
        else:
            cur = joined
    if cur:
        rows.append(cur)
    if elide and rows and advance(fm, rows[-1]) > width:
        rows[-1] = fm.elidedText(rows[-1], Qt.TextElideMode.ElideRight, width)
    return rows[:maxrows] or [""]


