class Clock:
    def __init__(self, transport=None) -> None:
        self.io = transport if transport is not None else MprisTransport()
        self.lock = threading.RLock()
        self.tid: str | None = None
        self.status = "Paused"
        self._pos = 0.0
        self._raw = 0.0
        self._at = mono()
        self.meta: dict = {}
        self._pos_tid: str | None = None
        self._slew = 0.0
        self._slew_at = 0.0
        self._pinned: str | None = None
        self._resyncing = False
        self.volume: float | None = None
        self._vol_set_at = 0.0
        self.unpause_delay = UNPAUSE_DELAY
        self.unpause_fixed = False
        self._resumed_at = 0.0
        self._bias = 0.0
        self._resume_pos = 0.0
        self._resume_lead = 0.0
        self._bias_tid: str | None = None
        self._audio_held = False    # the player says its audio is not moving (Mild Lyrics' own)

    def _drop(self) -> None:
        self.io.drop()

    def poll(self, pin_pause: bool = True) -> None:
        """Ask the player where it is and take the answer (`read` is the round
        trip, `apply` the arithmetic, for the editor's thread split)."""
        try:
            want_vol = self.wants_volume()
            got = self.io.read(want_vol)
        except Exception as e:
            follow_log("player", "clock-error", err=repr(e)[:200],
                       was_tid=self.tid)
            self._drop()
            self.status = "Error"
            self.last_error = str(e) or e.__class__.__name__
            return
        self.apply(got, want_vol, pin_pause)

    def wants_volume(self) -> bool:
        return mono() - self._vol_set_at > 1.0

    def apply(self, got: dict, want_vol: bool = True,
              pin_pause: bool = True) -> None:
        """Take a reading. Arithmetic only -- no player is spoken to here."""
        with self.lock:
            self._apply(got, want_vol, pin_pause)

    def _apply(self, got: dict, want_vol: bool, pin_pause: bool) -> None:
        try:
            was_playing = self.status == "Playing"
            held = self._raw
            tid, status = got["tid"], got["status"]
            pos, at = got["pos"], got["at"]
            engine = str(got.get("source") or "") == "engine"
            if want_vol:
                self.volume = got.get("volume")
            self.tid, self.status = tid, status
            self.meta = got["meta"]
            resumed = (status == "Playing" and not was_playing
                       and tid == self._pos_tid)
            seeked = resumed and abs(pos - held) > SEEK_JUMP
            if seeked:
                resumed = False
            jumped = (not resumed and status == "Playing" and was_playing
                      and tid == self._pos_tid and self._at
                      and at - self._resumed_at > RESUME_SETTLE
                      and abs(pos - (self._raw + (at - self._at))) > SLEW_MAX)
            if not resumed and (status != "Playing" or tid != self._bias_tid
                                or jumped or seeked):
                self._bias = 0.0
            elif (not resumed and self._at and not self.unpause_fixed
                    and at - self._resumed_at <= RESUME_MEASURE):
                free = self._resume_pos + (at - self._resumed_at)
                want = self._resume_lead + (pos - free)
                read = (_within(want, _measured_cap(self.unpause_delay))
                        if abs(want) > _step_floor(got) and not engine else 0.0)
                self._bias = read + _stated_push(self.unpause_delay)
            if resumed and self.unpause_fixed:
                self._resume_lead = self.unpause_delay
                self._resume_pos = pos
                self._bias = self.unpause_delay
                self._resumed_at = at
            elif resumed:
                self._resume_lead = (pos - held) - max(0.0, at - self._at)
                self._resume_pos = pos
                read = (_within(self._resume_lead,
                                 _measured_cap(self.unpause_delay))
                        if abs(self._resume_lead) > _step_floor(got)
                        and not engine else 0.0)
                self._bias = read + _stated_push(self.unpause_delay)
                self._resumed_at = at
            if str(got.get("source") or "") == "local":
                # Mild Lyrics' own player: its position is the decoder's, exact on resume
                # and after a seek. The resume hold is for players that lag their own
                # clock (Spotify); here it only measured noise, a new offset each pause.
                self._bias = 0.0
            hold = bool(got.get("held")) and status == "Playing"
            was_held, self._audio_held = self._audio_held, hold
            stale = (not resumed and not hold and status == "Playing" and tid == self._pos_tid
                     and pos == self._raw and at - self._at < STALE_HOLD)
            if not stale:
                held_back = pos - self._bias
                if (tid == self._pos_tid and status == "Playing"
                        and was_playing and self._at and not hold and not was_held
                        and at - self._resumed_at > RESUME_SETTLE):
                    # Rebase from the position actually being displayed, including
                    # any unfinished slew. Readings can arrive faster than SLEW_TIME.
                    shown = self.position(at)
                    d = held_back - shown
                    self._slew = -d if abs(d) <= SLEW_MAX else 0.0
                    self._slew_at = at
                else:
                    # A pause, track change, seek/resume or audio hold must not
                    # inherit a correction belonging to the previous clock anchor.
                    self._slew = 0.0
                self._pos, self._at, self._pos_tid = held_back, at, tid
                self._bias_tid = tid
                self._raw = pos
            if status == "Playing" or tid != self._pinned:
                self._pinned = None
            if (pin_pause and not self._pinned and status == "Paused"
                    and not was_playing and tid and pos == held):
                self._pinned = tid
                self._pin(pos)
        except Exception as e:
            follow_log("player", "clock-error", err=repr(e)[:200],
                       was_tid=self.tid)
            self._drop()
            self.status = "Error"
            self.last_error = str(e) or e.__class__.__name__

    @property
    def resumed_at(self) -> float:
        """When playback last resumed, by this clock's reckoning."""
        return self._resumed_at

    @property
    def resume_hold(self) -> float:
        """How far the words are moved for the last unpause: positive holds
        them back, negative pushes them on."""
        return self._bias

    def position(self, now: float | None = None) -> float:
        """Where the song is -- at `now` on the mono clock, which the window
        passes as the time of the frame it is making (LyricsView.frame_now),
        and otherwise this moment."""
        with self.lock:
            if self.status != "Playing":
                return self._pos
            if self._audio_held:
                return self._pos
            if now is None:
                now = mono()
            pos = self._pos + (now - self._at)
            if self._slew:
                k = 1.0 - (now - self._slew_at) / SLEW_TIME
                if k <= 0.0:
                    self._slew = 0.0
                else:
                    pos += self._slew * k
            length = self.meta.get("length", 0.0)
            return min(pos, length) if length else pos

    def _pin(self, pos: float) -> None:
        """Silently seek a paused player to where it already says it is, to
        correct its audio drift; failure is ignored."""
        length = self.meta.get("length", 0.0)
        if pos < PIN_EDGE or (length and pos > length - PIN_EDGE):
            return
        if getattr(self.io, "app", DEVICE_APP) != DEVICE_APP:
            return
        try:
            self.io.seek(pos)
        except Exception:
            self._drop()

    def seek(self, seconds: float, keep_hold: bool = False) -> None:
        """Send the player somewhere; a hand seek drops the unpause hold,
        `keep_hold` (resyncs) keeps it."""
        self._slew = 0.0
        began = mono()
        try:
            self.io.seek(seconds)
        except Exception as e:
            follow_log("player", "clock-seek-failed", to=seconds,
                       err=repr(e)[:200])
            self._drop()
            return
        with self.lock:
            self._pos = self._raw = max(0.0, seconds)
            self._at = began + (mono() - began) / 2
            self._audio_held = bool(getattr(self.io, "holds_seeks", False))
            if not keep_hold:
                self._bias = 0.0

    def set_volume(self, v: float) -> None:
        v = max(0.0, min(1.0, v))
        try:
            self.io.set_volume(v)
            self.volume, self._vol_set_at = v, mono()
        except Exception:
            self._drop()

    def resync(self) -> None:
        """Seek to where we already are, re-read from the player, to flush
        Spotify's audio pipeline after a gapless hand-off."""
        if self.status != "Playing":
            return
        try:
            fresh = float(self.io.read(False).get("pos") or 0.0)
        except Exception:
            self._drop()
            return
        self.seek(max(0.0, fresh - RESYNC_NUDGE), keep_hold=True)
        self._pos_tid = None

    def resync_soon(self) -> None:
        """The same resync on a thread of its own, one at a time."""
        if self.status != "Playing" or self._resyncing:
            return
        self._resyncing = True

        def run() -> None:
            try:
                self.resync()
            except Exception:                   # noqa: BLE001
                pass
            finally:
                self._resyncing = False

        threading.Thread(target=run, name="resync", daemon=True).start()

    def command(self, name: str) -> bool:
        """PlayPause / Next / Previous; False where the player would not."""
        try:
            self.io.command(name)
            return True
        except Exception:
            self._drop()
            return False


# --------------------------------------------------------------------------
# --------------------------------------------------------------------------
class Pump(QThread):
    """The thread that reads Spotify's position every frame, so a seek in
    Spotify's own window is stale for one frame; reads only, writes go
    direct."""

    read = pyqtSignal()

    def __init__(self, clock, every: float = SAMPLE_MS / 1000.0,
                 pin_pause=True, parent=None) -> None:
        super().__init__(parent)
        self.clock = clock
        self.every = every
        self.pin_pause = pin_pause
        self.last_tid: str | None = None
        self._seen: tuple | None = None
        self._wake = threading.Event()
        self._going = True

    def stop(self) -> None:
        self._going = False
        self._wake.set()
        self.wait(2000)

    def _news(self) -> bool:
        """Whether the reading just taken needs the GUI thread: track or status
        changed, or a position moved while paused."""
        with self.clock.lock:
            now = (self.clock.tid, self.clock.status, self.clock._raw)
        was, self._seen = self._seen, now
        if was is None or now[:2] != was[:2]:
            return True
        return now[1] != "Playing" and abs(now[2] - was[2]) > READ_MOVED

    def run(self) -> None:                                  # pragma: no cover
        while self._going:
            try:
                want_vol = self.clock.wants_volume()
                got = self.clock.io.read(want_vol)
            except Exception as e:              # noqa: BLE001
                self.clock._drop()
                self.clock.status = "Error"
                self.clock.last_error = str(e) or e.__class__.__name__
                got = None
            except BaseException:
                self.clock.status = "Error"
                got = None
            if got is not None:
                pin = self.pin_pause
                self.clock.apply(got, want_vol,
                                 bool(pin() if callable(pin) else pin))
                self.last_tid = got.get("tid") or None
                self.last_stamp = float(got.get("stamp") or 0.0)
            if self._going and self._news():
                self.read.emit()
            self._wake.wait(self.every if self.clock.status != "Error"
                            else POLL_MS / 1000.0)
            self._wake.clear()


