JS_RECENTS = """(async () => {
  try {
    const out = {tracks: [], ctx: []};
    try {
      const h = await Spicetify.Platform.PlayHistoryAPI.getContents();
      for (const it of ((h||{}).items||[]).slice(0, %d)) {
        if (!it || it.type !== "track") continue;
        out.tracks.push({
          uri: it.uri || "", name: it.name || "",
          sub: (it.artists||[]).map(a => a.name).filter(Boolean).join(", "),
          art: (((it.album||{}).images||[])[0]||{}).url || "",
          ms: ((it.duration||{}).milliseconds) || 0});
      }
    } catch (e) {}
    try {
      const c = await Spicetify.Platform.RecentlyPlayedAPI.getContexts(%d);
      for (const it of (c||[]).slice(0, %d)) {
        if (!it || !it.uri) continue;
        out.ctx.push({
          uri: it.uri, name: it.name || "",
          sub: (it.artists||[]).map(a => a.name).filter(Boolean).join(", ")
               || (it.type || ""),
          art: ((it.images||[])[0]||{}).url || ""});
      }
    } catch (e) {}
    return out;
  } catch (e) { return null; }
})()"""

JS_QUEUE = """(async () => {
  try {
    const q = await Spicetify.Platform.PlayerAPI.getQueue();
    const one = (it, src) => {
      if (!it || !it.uri) return null;
      const md = it.metadata || {};
      return {uri: it.uri, uid: it.uid || "",
              name: it.name || md.title || "",
              album: md.album_title || (it.album || {}).name || "",
              album_artist: md.album_artist_name
                || ((((it.album || {}).artists) || [])[0] || {}).name || "",
              sub: (it.artists || []).map(a => a.name).filter(Boolean).join(", ")
                   || md.artist_name || "",
              art: ((it.images || [])[0] || {}).url || md.image_url || "",
              ms: (it.duration || {}).milliseconds || Number(md.duration || 0) || 0,
              src: src};
    };
    const out = {current: one((q || {}).current, "now"), items: []};
    for (const it of ((q || {}).queued || []).slice(0, 60)) {
      const r = one(it, "queued"); if (r) out.items.push(r);
    }
    for (const it of ((q || {}).nextUp || []).slice(0, 60)) {
      const r = one(it, "next"); if (r) out.items.push(r);
    }
    return out;
  } catch (e) { return null; }
})()"""

JS_SUGGEST = """(async () => {
  const out = {related: [], playlists: [], top: [], mine: [], artist: ""};
  // Resolve who is playing here rather than shuttling it in: the fetcher
  // thread already holds the connection, and this way the answer can never be
  // for a track that has since changed.
  let A = %s;
  if (!A) {
    try {
      const d = Spicetify.Player.data, it = d && (d.item || d.track);
      A = (((it || {}).artists || [])[0] || {}).uri || "";
    } catch (e) { A = ""; }
  }
  out.artist = A || "";
  const img = o => (((o || {}).sources) || [])[0] || {};
  if (A) {
    try {
      const r = await Spicetify.GraphQL.Request(
        Spicetify.GraphQL.Definitions.queryArtistRelated, {uri: A});
      const it = (((((r.data || {}).artistUnion || {}).relatedContent || {})
                   .relatedArtists) || {}).items || [];
      for (const x of it.slice(0, 12))
        out.related.push({uri: x.uri, name: (x.profile || {}).name || "",
          sub: "Artist",
          art: img(((x.visuals || {}).avatarImage)).url || ""});
    } catch (e) {}
    try {
      const r = await Spicetify.GraphQL.Request(
        Spicetify.GraphQL.Definitions.queryArtistDiscoveredOn, {uri: A});
      const it = (((((r.data || {}).artistUnion || {}).relatedContent || {})
                   .discoveredOnV2) || {}).items || [];
      for (const x of it.slice(0, 20)) {
        const d = x.data || {};
        // the list is padded with GenericError entries for anything the
        // account cannot see; those have no uri and must not become cards
        if (d.__typename !== "Playlist" || !d.uri) continue;
        out.playlists.push({uri: d.uri, name: d.name || "",
          sub: ((d.ownerV2 || {}).data || {}).name || "Playlist",
          art: img((((d.images || {}).items || [])[0])).url || ""});
      }
    } catch (e) {}
    try {
      const r = await Spicetify.GraphQL.Request(
        Spicetify.GraphQL.Definitions.queryArtistOverview, {uri: A, locale: ""});
      const it = ((((r.data || {}).artistUnion || {}).discography || {})
                  .topTracks || {}).items || [];
      for (const x of it.slice(0, 12)) {
        const t = x.track || {};
        if (!t.uri) continue;
        out.top.push({uri: t.uri, name: t.name || "",
          sub: ((t.artists || {}).items || [])
                 .map(a => (a.profile || {}).name).filter(Boolean).join(", "),
          art: img(((t.albumOfTrack || {}).coverArt)).url || ""});
      }
    } catch (e) {}
  }
  try {
    const r = await Spicetify.Platform.RootlistAPI.getContents({limit: 30});
    for (const x of (r.items || [])) {
      if (x.type !== "playlist" || !x.uri) continue;
      out.mine.push({uri: x.uri, name: x.name || "",
        sub: "Playlist", art: ((x.images || [])[0] || {}).url || ""});
      if (out.mine.length >= 12) break;
    }
  } catch (e) {}
  return out;
})()"""

JS_DISCOVER = """(async () => {
  const out = {seed: "", because: [], songs: []};
  const img = o => (((o || {}).sources) || [])[0] || {};
  let hist = [];
  try {
    const h = await Spicetify.Platform.PlayHistoryAPI.getContents();
    hist = (h || {}).items || [];
  } catch (e) { return out; }
  if (!hist.length) return out;

  const heard = new Set();
  const tally = new Map();
  hist.forEach((x, i) => {
    if (x.uri) heard.add(x.uri);
    // newest first, so the top of the list counts for more -- what you played
    // an hour ago should steer this more than what you played last week
    const w = 1 + (hist.length - i) / hist.length;
    for (const a of (x.artists || [])) {
      if (!a.uri) continue;
      const e = tally.get(a.uri) || {name: a.name || "", score: 0};
      e.score += w;
      tally.set(a.uri, e);
    }
  });

  const cur = %s;   // excluded: whoever is playing already has their own shelves
  const seeds = [...tally.entries()].filter(e => e[0] !== cur)
                  .sort((a, b) => b[1].score - a[1].score).slice(0, 3);
  if (!seeds.length) return out;
  out.seed = seeds[0][1].name;

  const rel = new Map();
  for (const [uri] of seeds) {
    try {
      const r = await Spicetify.GraphQL.Request(
        Spicetify.GraphQL.Definitions.queryArtistRelated, {uri: uri});
      const it = (((((r.data || {}).artistUnion || {}).relatedContent || {})
                   .relatedArtists) || {}).items || [];
      for (const x of it.slice(0, 6)) {
        // skip anyone already in the history: a recommendation should be
        // something new, not a list of the artists it was derived from
        if (!x.uri || tally.has(x.uri) || rel.has(x.uri)) continue;
        rel.set(x.uri, {uri: x.uri, name: (x.profile || {}).name || "",
                        sub: "Artist",
                        art: img((x.visuals || {}).avatarImage).url || ""});
      }
    } catch (e) {}
  }
  out.because = [...rel.values()].slice(0, 12);

  for (const a of [...rel.values()].slice(0, 5)) {
    if (out.songs.length >= 12) break;
    try {
      const r = await Spicetify.GraphQL.Request(
        Spicetify.GraphQL.Definitions.queryArtistOverview, {uri: a.uri, locale: ""});
      const tt = ((((r.data || {}).artistUnion || {}).discography || {})
                  .topTracks || {}).items || [];
      for (const x of tt.slice(0, 3)) {
        const t = x.track || {};
        if (!t.uri || heard.has(t.uri)) continue;
        out.songs.push({uri: t.uri, name: t.name || "",
          sub: ((t.artists || {}).items || [])
                 .map(z => (z.profile || {}).name).filter(Boolean).join(", "),
          art: img((t.albumOfTrack || {}).coverArt).url || ""});
        if (out.songs.length >= 12) break;
      }
    } catch (e) {}
  }
  return out;
})()"""

JS_TRACKS = """(async () => {
  const ids = %s;
  const out = [];
  for (const id of ids) {
    try {
      const r = await Spicetify.GraphQL.Request(
        Spicetify.GraphQL.Definitions.getTrack, {uri: "spotify:track:" + id});
      const t = ((r||{}).data||{}).trackUnion;
      if (!t || !t.name) { out.push({id: id, name: "", artist: ""}); continue; }
      const a = ((t.firstArtist||{}).items) || ((t.artists||{}).items) || [];
      out.push({id: id, name: t.name,
                artist: a.map(x => (x.profile||{}).name).filter(Boolean).join(", ")});
    } catch (e) { out.push({id: id, name: "", artist: ""}); }
  }
  return out;
})()"""

JS_PLAY_ID = """(async () => {
  const id = %s, D = Spicetify.GraphQL.Definitions;
  const ask = async (def, vars) => {
    try { return ((await Spicetify.GraphQL.Request(def, vars)) || {}).data || {}; }
    catch (e) { return {}; }
  };
  const t = (await ask(D.getTrack, {uri: "spotify:track:" + id})).trackUnion;
  let kind = "", name = "";
  if (t && t.name) { kind = "track"; name = t.name; }
  else {
    const a = (await ask(D.getAlbum, {uri: "spotify:album:" + id, locale: "",
                                      offset: 0, limit: 1})).albumUnion;
    if (a && a.uri) { kind = "album"; name = a.name || ""; }
  }
  if (!kind) return null;
  await Spicetify.Player.playUri("spotify:" + kind + ":" + id);
  return {kind: kind, name: name};
})()"""


MOTION_DIR = INDEX.parent / "motion"
MOTION_FPS = 30
MOTION_SECS = 35.0
MOTION_PX = 720
MOTION_BUDGET = 192 << 20
MOTION_SLICE_MS = 4.0
MOTION_MEMO = MOTION_DIR / "known.json"
MOTION_MISS_TTL = 30 * 86400
AMP_VIDEO = re.compile(r"<amp-ambient-video[^>]+src=\"([^\"]+\.m3u8)\"")
HLS_VARIANT = re.compile(r"^#EXT-X-STREAM-INF:.*?RESOLUTION=(\d+)x(\d+)", re.M)
APPLE_UA = LS.APPLE_UA
_apple_get = LS._plain_page


def best_variant(master_url: str) -> str:
    """The highest-resolution rendition in an HLS master playlist, so ffmpeg is
    handed one stream."""
    try:
        text = _apple_get(master_url)
    except Exception:
        return master_url
    lines = text.splitlines()
    best, best_url = 0, ""
    for i, line in enumerate(lines):
        m = HLS_VARIANT.match(line)
        if not m:
            continue
        for nxt in lines[i + 1:i + 4]:
            nxt = nxt.strip()
            if nxt and not nxt.startswith("#"):
                if int(m.group(1)) > best:
                    best, best_url = int(m.group(1)), urllib.parse.urljoin(
                        master_url, nxt)
                break
    return best_url or master_url


def _akey(s: str) -> str:
    return "".join(c for c in (s or "").lower() if c.isalnum())


def _loose(a: str, b: str) -> bool:
    """Same name allowing for editions and suffixes, in either direction."""
    ka, kb = _akey(a), _akey(b)
    if not ka or not kb:
        return False
    return ka == kb or (len(ka) >= 4 and ka in kb) or (len(kb) >= 4 and kb in ka)


EDITION = re.compile(
    r"\s*(?:[\(\[][^()\[\]]*(?:deluxe|edition|version|remaster|expanded|"
    r"anniversary|special|bonus|explicit|reissue)[^()\[\]]*[\)\]]"
    r"|-\s*(?:single|ep|deluxe\b.*|.*\bedition\b.*|.*\bversion\b.*))\s*$",
    re.I)
AM_ALBUM = re.compile(r"music\.apple\.com/[a-z]{2}/album/[^/\"?]+/(\d+)")


def _plain(name: str) -> str:
    """The record's name with its edition suffix off, or the name unchanged."""
    out = name
    for _ in range(2):
        out = EDITION.sub("", out)
    return out.strip() or name


def _itunes_albums(term: str) -> list:
    """What the iTunes Search API has for this term. Fast, and often enough."""
    q = urllib.parse.urlencode({"term": term, "entity": "album", "limit": 10})
    try:
        raw = _apple_get(f"https://itunes.apple.com/search?{q}")
        return (json.loads(raw) or {}).get("results") or []
    except Exception:
        return []


def _web_albums(term: str) -> list:
    """Albums from music.apple.com's search page, looked up to come out like
    Search API hits."""
    try:
        html = _apple_get("https://music.apple.com/us/search?term="
                          + urllib.parse.quote(term))
    except Exception:
        return []
    ids: list[str] = []
    for m in AM_ALBUM.finditer(html):
        if m.group(1) not in ids:
            ids.append(m.group(1))
        if len(ids) >= 12:
            break
    if not ids:
        return []
    try:
        raw = _apple_get("https://itunes.apple.com/lookup?id=" + ",".join(ids))
        hits = (json.loads(raw) or {}).get("results") or []
    except Exception:
        return []
    return [h for h in hits if h.get("wrapperType") == "collection"]


def motion_url(artist: str, album: str, title: str = "") -> str:
    """The animated cover's stream for this record, or "": album search (title
    and artist checked), then the album page."""
    single = not album or _loose(_plain(album), _plain(title))
    name = album or title
    if not name.strip() or not artist.strip():
        return ""
    terms = []
    for term in (f"{artist} {name}", f"{artist} {_plain(name)}",
                 f"{artist} {title}" if single and title else ""):
        term = " ".join(term.split())
        if term and term not in terms:
            terms.append(term)
    keep, seen = [], set()
    for finder in (_itunes_albums, _web_albums):
        for term in terms:
            for hit in finder(term):
                url = (hit.get("collectionViewUrl") or "").split("?")[0]
                theirs = hit.get("collectionName") or ""
                by = hit.get("artistName") or ""
                if not url or url in seen:
                    continue
                if not (_loose(name, theirs) and _loose(artist, by)):
                    continue
                seen.add(url)
                rank = 2
                if _akey(theirs) == _akey(name):
                    rank = 0
                elif _akey(_plain(theirs)) == _akey(_plain(name)):
                    rank = 1
                keep.append((rank, url))
        if keep:
            break
    keep.sort(key=lambda r: r[0])
    for _, url in keep:
        try:
            found = AMP_VIDEO.search(_apple_get(url))
        except Exception:
            continue
        if found:
            return found.group(1)
    return ""


class Thinned(list):
    """Frames already cut down to what the screen can hold, with the step
    that was used -- the animation plays at 1/step of the rate it was made at
    -- and the middle frame of the whole animation, which is what the wall
    and the palette are drawn from."""
    step = 1
    middle = None


class MotionArt(QObject):
    """The animated cover as frames, fetched and decoded off the GUI thread;
    any failure leaves the still cover."""
    ready = pyqtSignal(str, object)
    looked = pyqtSignal(str, object)

    def __init__(self) -> None:
        super().__init__()
        self.q: queue.Queue = queue.Queue()
        self.seen: set[str] = set()
        self.stop = False
        self._known: dict | None = None
        self._lock = threading.Lock()
        # Memory use (apply_memory): "low" hands out a MotionStream instead
        # of frames; "more" decodes up to ahead_max queued albums early.
        self.stream = False
        self.ahead_max = 0
        self.keep_memo = True                 # minimal reads known.json per job
        self._later: deque = deque()          # ahead jobs, run when idle
        self._ahead: OrderedDict = OrderedDict()   # key -> (frames, look)
        self._promote: set[str] = set()       # ahead in flight, now playing
        threading.Thread(target=self._work, daemon=True).start()

    def want(self, key: str, artist: str, album: str, title: str = "",
             cap: int = MOTION_PX) -> None:
        """Ask for this album's animation unless it is in flight (`seen`);
        `cap` is the widest a frame will be drawn."""
        with self._lock:
            early = self._ahead.pop(key, None)
            if early is None and key in self.seen:
                self._promote.add(key)
                return
            if early is None:
                self.seen.add(key)
        if early is not None:          # decoded while the track before played
            frames, look = early
            if look is not None:
                self.looked.emit(key, look)
            self.ready.emit(key, frames)
            return
        self.q.put((key, artist, album, title, cap, self.stream, False))

    def want_ahead(self, key: str, artist: str, album: str, title: str,
                   cap: int) -> None:
        """Decode a queued album's animation now and keep it for when it
        plays (Memory use "more"); runs only while nothing else is asked."""
        with self._lock:
            if (not self.ahead_max or key in self.seen or key in self._ahead
                    or any(j[0] == key for j in self._later)):
                return
            self._later.append((key, artist, album, title, cap, False, True))
        self.q.put(())                  # wake the worker

    def forget_ahead(self) -> None:
        with self._lock:
            self._ahead.clear()
            self._later.clear()

    def _dir(self, key: str) -> pathlib.Path:
        return MOTION_DIR / hashlib.sha1(key.encode()).hexdigest()[:16]

    def _next(self):
        """The next job: anything asked for now before anything ahead. An
        empty tuple on the queue only wakes the worker."""
        while True:
            try:
                job = self.q.get_nowait()
            except queue.Empty:
                with self._lock:
                    if self._later:
                        job = self._later.popleft()
                        self.seen.add(job[0])
                        return job
                job = self.q.get()
            if job != ():
                return job

    def _work(self) -> None:
        while not self.stop:
            job = self._next()
            if job is None or self.stop:
                return
            self._job(*job)

    def _job(self, key: str, artist: str, album: str, title: str, cap: int,
              stream: bool, ahead: bool) -> None:
        """One album. Its own frame so its frames die with it: held in
        _work's locals they outlived the album until the next one."""
        try:
            frames = self._frames(key, artist, album, title, cap, stream)
        except Exception:
            frames = []
        if not self.keep_memo:
            self._known = None
        look = None
        if frames and not self.stop:
            mid = frames.middle
            if mid is None and not isinstance(frames, MS.MotionStream):
                mid = frames[len(frames) // 2]      # a stream makes QPixmaps
            try:
                look = cover_look(mid) if mid is not None else None
            except Exception:                               # noqa: BLE001
                look = None
            frames.middle = mid = None     # full size, needed only for the look
        with self._lock:
            self.seen.discard(key)
            keep = ahead and key not in self._promote
            self._promote.discard(key)
            if keep and frames:
                self._ahead[key] = (frames, look)
                while len(self._ahead) > max(1, self.ahead_max):
                    self._ahead.popitem(last=False)
        if keep or not frames or self.stop:
            if keep:
                MM.trim_heap_soon()
            return
        if look is not None:
            self.looked.emit(key, look)
        self.ready.emit(key, frames)

    def _memo(self) -> dict:
        """What Apple has already answered, album by album. Read once."""
        if self._known is None:
            try:
                self._known = json.loads(MOTION_MEMO.read_text())
            except Exception:
                self._known = {}
        return self._known

    def _remember(self, key: str, url: str, artist: str, album: str) -> None:
        """Record the answer. An empty url is a miss, and that is the entry
        worth having -- it is the one that saves a search next time."""
        memo = self._memo()
        memo[key] = {"url": url, "at": int(time.time()),
                     "artist": artist, "album": album,
                     "dir": self._dir(key).name}
        try:
            MOTION_MEMO.parent.mkdir(parents=True, exist_ok=True)
            tmp = MOTION_MEMO.with_suffix(".tmp")
            tmp.write_text(json.dumps(memo, indent=1))
            tmp.replace(MOTION_MEMO)
        except Exception:
            pass

    def _decode(self, url: str, out: pathlib.Path) -> list:
        """The stream, turned into frames on disk. Empty if that did not work."""
        out.mkdir(parents=True, exist_ok=True)
        # Two decode threads, one filter thread and low priority, so a first
        # decode does not slow the window's paints.
        cmd = ["ffmpeg", "-hide_banner", "-loglevel", "error",
               "-threads", "2", "-filter_threads", "1",
               "-user_agent", APPLE_UA, "-i", best_variant(url),
               "-t", str(MOTION_SECS),
               "-vf", f"fps={MOTION_FPS},scale={MOTION_PX}:-1",
               "-q:v", "2",
               "-frames:v", str(int(MOTION_FPS * MOTION_SECS)),
               os.path.join(noconsole.real_path(out), "f_%03d.jpg")]
        flags = 0x00004000 if os.name == "nt" else 0     # BELOW_NORMAL_PRIORITY_CLASS
        if os.name != "nt" and shutil.which("nice"):
            cmd = ["nice", "-n", "10", *cmd]
        try:
            noconsole.run(cmd, timeout=120, check=False, creationflags=flags,
                          stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except FileNotFoundError:
            return []
        except Exception:
            return []
        return sorted(out.glob("f_*.jpg"))

    def _frames(self, key: str, artist: str, album: str, title: str = "",
                cap: int = MOTION_PX, stream: bool = False):
        """The animation's frames, only as many as the screen budget keeps,
        each at most `cap` wide; a MotionStream over the files where
        `stream`."""
        out = self._dir(key)
        have = sorted(out.glob("f_*.jpg")) if out.is_dir() else []
        if not have:
            memo = self._memo().get(key) or {}
            recent = time.time() - float(memo.get("at") or 0) < MOTION_MISS_TTL
            if memo and not memo.get("url") and recent:
                return []
            url = memo.get("url") or ""
            have = self._decode(url, out) if url else []
            if not have:
                url = motion_url(artist, album, title)
                have = self._decode(url, out) if url else []
            self._remember(key, url if have else "", artist, album)
        if not have:
            return []
        # The look (wall, palette) comes off the middle frame at full size,
        # as it always has; the frames themselves are held at `cap`.
        middle = QImage()
        if not middle.load(str(have[len(have) // 2])) or middle.isNull():
            middle = None
        if stream:
            return MS.MotionStream(have, cap, middle)
        fits = max(1, MOTION_BUDGET // max(1, cap * cap * 4))
        step = max(1, -(-len(have) // fits))
        imgs = Thinned()
        imgs.step = step
        for path in have[::step]:
            img = MS.decode(path, cap)
            if img is not None:
                imgs.append(img)
        imgs.middle = middle
        return imgs


class ArtCache(QObject):
    """Thumbnails for the browse grid: a small worker pool with a disk cache;
    workers emit QImage only."""
    loaded = pyqtSignal(str, object)
    BUDGET = 32 << 20
    WORKERS = 6         # two loaded a screen of covers one by one; mostly waiting on the network
    STALE = 2.0         # s: not drawn for this long (scrolled past), not fetched

    def __init__(self, size: int = 320) -> None:
        super().__init__()
        self.size = size
        self.pix: OrderedDict[str, QPixmap] = OrderedDict()
        self.bytes = 0
        # Newest first: scrolling a long list queued every row passed, and the
        # ones on screen waited behind all of them.
        self.q: queue.LifoQueue = queue.LifoQueue()
        self.seen: set[str] = set()
        self.asked: dict[str, float] = {}
        self.full: dict[str, str] = {}      # sized url -> the url it was made from
        self.stop = False
        self._lock = threading.Lock()
        for _ in range(self.WORKERS):
            threading.Thread(target=self._work, daemon=True).start()

    def get(self, url: str, px: float = 0.0):
        """Called from paint. Returns a pixmap, or None and queues a fetch; `px` is
        the size it is drawn at in device pixels, 0 for the picture as given."""
        if not url:
            return None
        want = sized_art(url, px) if px else url
        for u in (want, url):
            hit = self.pix.get(u)
            if hit is not None:
                self.pix.move_to_end(u)
                return hit
        self.asked[want] = mono()
        with self._lock:
            if want in self.seen:
                return None
            self.seen.add(want)
            self.full[want] = url
        self.q.put(want)
        return None

    def put(self, url: str, img) -> None:
        """Store a thumbnail as a QPixmap (GUI thread), held to BUDGET bytes,
        least recently drawn first."""
        pm = QPixmap.fromImage(img)
        was = self.pix.pop(url, None)
        if was is not None:
            self.bytes -= _pm_bytes(was)
        self.pix[url] = pm
        self.bytes += _pm_bytes(pm)
        while self.bytes > self.BUDGET and len(self.pix) > 1:
            gone, old = self.pix.popitem(last=False)
            self.bytes -= _pm_bytes(old)
            with self._lock:
                self.seen.discard(gone)

    def _work(self) -> None:
        while not self.stop:
            url = self.q.get()
            if url is None or self.stop:
                return
            if mono() - self.asked.get(url, 0.0) > self.STALE:
                with self._lock:
                    self.seen.discard(url)          # asked again if it comes back on screen
                continue
            full = self.full.get(url, url)
            # A full-size copy already on disk beats fetching the small one.
            have_full = full != url and not art_path(url).exists() and art_path(full).exists()
            raw = art_bytes(full) if have_full else art_bytes(url)
            if not raw and full != url and not have_full:
                raw = art_bytes(full)               # no such size on the CDN
            img = QImage()
            if raw:
                img.loadFromData(raw, image_format(raw))
            if img.isNull() or self.stop:
                continue
            if max(img.width(), img.height()) > self.size:
                img = img.scaled(self.size, self.size,
                                 Qt.AspectRatioMode.KeepAspectRatioByExpanding,
                                 Qt.TransformationMode.SmoothTransformation)
            if not self.stop:
                self.loaded.emit(url, img)


def _above(order: list, a: str, b: str) -> bool:
    """Whether `a` is consulted before `b`. False if either is switched off."""
    return a in order and b in order and order.index(a) < order.index(b)


_people = LS.people


def _pick_names(meta: dict) -> tuple:
    """A song's title and first artist as a kept pick is checked against, loosely."""
    import stream_source as SS
    title, artist = str(meta.get("title") or ""), str(meta.get("artist") or "")
    title = SS.drop_credited_feat(title, artist)
    squash = lambda t: re.sub(r"[\W_]+", "", t.casefold())      # noqa: E731
    return squash(title), squash(re.split(r",|&", artist)[0])


class Fetcher(QObject):
    ready = pyqtSignal(str, object, object)
    ahead_ready = pyqtSignal(str, object)      # a fetched-ahead song's lines
    artists_ready = pyqtSignal(str, object)
    beat_ready = pyqtSignal(str, object)
    index_ready = pyqtSignal(object)
    index_progress = pyqtSignal(int)
    genius_ready = pyqtSignal(str, object, object)
    recents_ready = pyqtSignal(object, object)
    catsearch_ready = pyqtSignal(str, object)
    id_played = pyqtSignal(str, object)
    gsearch_ready = pyqtSignal(str, object)
    gmatch_ready = pyqtSignal(object, object)
    backfill_progress = pyqtSignal(int, int)
    backfill_ready = pyqtSignal(object)
    queue_ready = pyqtSignal(object)
    suggest_ready = pyqtSignal(object)
    discover_ready = pyqtSignal(object)
    ne_roman_ready = pyqtSignal(str, object)
    roman_ahead_ready = pyqtSignal(str, object, object)    # tid, Genius's mapping or None, NetEase's
    apple_ready = pyqtSignal(str, object)
    card_ready = pyqtSignal(str, object)
    album_ready = pyqtSignal(str, object)
    source_trouble = pyqtSignal(str, object)
    people_met = pyqtSignal(str, object)

    def __init__(self, port: int, split: str, threshold: float) -> None:
        super().__init__()
        self.port, self.split, self.threshold = port, split, threshold
        self.cdp = None
        self._want: str | None = None
        self.stop = False
        self._index = False
        self._index_at: int | None = None
        self._index_songs: list[dict] = []
        self._doing: tuple | None = None
        self._doing_busy = False
        self._genius: tuple | None = None
        self._ne_roman: tuple | None = None
        self._roman_ahead: list = []
        self._roman_thread = None
        self._apple: tuple | None = None
        self._card: tuple | None = None
        self._album: str | None = None
        self._meta: dict = {}
        self.spotify_lookup = False
        self._sid_cache: dict = {}
        self._sources: set = set()
        self._order: list = []
        self._people = LS.Roster()
        self._graft = True
        self._fold = True
        self._clean = True
        self.done: str = ""
        self._recents = False
        self._queue = False
        self._stood_in: str | None = None
        self._shown: tuple = ("", 0)
        self._suggest: str | None = None
        self._discover = False
        self._search: str | None = None
        self._search_busy = False
        self._gsearch: str | None = None
        self._gsearch_busy = False
        self._gmatch: dict | None = None
        self._backfill_ids: list = []
        self._backfill_at: int | None = None
        self._ahead: list = []
        self._ahead_told: dict = {}
        self._picks: dict = {}          # tid -> a coming song's finished pick (_pick_ahead)
        self._ahead_gen = 0
        self._ahead_thread: threading.Thread | None = None
        self._loaded: str | None = None
        self._loading: str | None = None
        self._beat_tid = ""
        self._kept: dict = {}
        self._wake = threading.Event()
        self._chores = threading.Event()
        self._lock = threading.Lock()
        # The lyric walks -- see run(). One number per walk started; only the
        # walk holding the latest one is the one anybody is waiting on.
        self._walk_no = 0
        self._walk_tid: str | None = None
        self._walk_live = False
        self._walk_again = False
        self._pending: dict[str, float] = {}
        self._backoff: dict[str, float] = {}
        self._here = threading.local()

    def request(self, tid: str, meta: dict | None = None, sources=None,
                order=None, graft=None, fold=None, clean=None,
                people=None) -> None:
        with self._lock:
            self._want = tid
            if meta:
                self._meta = dict(meta)
            if sources is not None:
                self._sources = set(sources)
            if order is not None:
                self._order = list(order)
            if graft is not None:
                self._graft = bool(graft)
            if fold is not None:
                self._fold = bool(fold)
            if clean is not None:
                self._clean = bool(clean)
            if people is not None:
                self._people = people
        self._beat_for(tid)
        self._wake.set()

    def walking(self, tid: str) -> bool:
        """Whether a walk for `tid` is out or queued: asking again would only
        queue one more behind it."""
        with self._lock:
            return (self._walk_live and self._walk_tid == tid) \
                or self._want == tid or tid in self._pending

    def _beat_for(self, tid: str) -> None:
        """Ask for the track's audio analysis on a thread of its own, once per
        track id seen in a row."""
        with self._lock:
            if not tid or tid == self._beat_tid:
                return
            self._beat_tid = tid
        threading.Thread(target=self._beat_ask, args=(tid,), name="beat",
                         daemon=True).start()

    def _beat_ask(self, tid: str) -> None:
        """One analysis ask, and a second on a fresh socket where the first
        failed before the page could answer."""
        t0 = mono()
        got = self._audio(tid, BEAT_WAIT_MS)
        if got is None and not self.stop and mono() - t0 < 1.0:
            with self._lock:
                still = self._beat_tid == tid
            if still:
                got = self._audio(tid, BEAT_WAIT_MS)
        if not self.stop:
            self.beat_ready.emit(tid, got)

    def request_card(self, tid: str, meta: dict) -> None:
        """Ask Apple Music what this track looks like, for players that cannot
        say (see LS.apple_song)."""
        with self._lock:
            self._card = (tid, dict(meta or {}))
        self._chores.set()

    def request_index(self) -> None:
        with self._lock:
            self._index = True

    def request_play(self, uri: str) -> None:
        """Play this, now. See `_act` for why it does not go in the queue."""
        self._act(("play", uri))

    def request_play_in(self, context: str, uri: str, seek_ms: int | None = None) -> None:
        """Play an album or playlist from one of its tracks, as picking a
        row in Spotify's own list does: the rest of it plays on after.
        `seek_ms`: from there in that track (it was already playing)."""
        self._act(("play_in", (context, uri, seek_ms)))

    def request_play_id(self, sid: str) -> None:
        """Play a bare Spotify id as a track or album; the answer comes back on
        id_played ({kind, name} or None)."""
        self._act(("play_id", sid))

    def request_recents(self) -> None:
        with self._lock:
            self._recents = True

    def request_queue(self) -> None:
        with self._lock:
            self._queue = True

    def request_skip(self, uri: str, uid: str) -> None:
        """Jump down the queue. Heard the moment it lands, like a play."""
        self._act(("skip", (uri, uid)))

    def _act(self, what: tuple) -> None:
        """Make the player do something on a thread of its own, one last-wins
        slot, so it never waits behind the lyric walk."""
        with self._lock:
            self._doing = what
            if self._doing_busy:
                return
            self._doing_busy = True
        threading.Thread(target=self._act_loop, daemon=True).start()

    def _act_loop(self) -> None:
        while not self.stop:
            with self._lock:
                what, self._doing = self._doing, None
                if what is None:
                    self._doing_busy = False
                    return
            kind, arg = what
            try:
                if kind == "play":
                    self._eval(f"Spicetify.Player.playUri({json.dumps(arg)})")
                elif kind == "play_in":
                    ctx, uri, seek = arg
                    at = f", seekTo: {int(seek)}" if seek else ""
                    self._eval(f"Spicetify.Player.playUri({json.dumps(ctx)}, {{}}, "
                               f"{{skipTo: {{uri: {json.dumps(uri)}}}{at}}})")
                elif kind == "play_id":
                    got = self._eval(JS_PLAY_ID % json.dumps(arg))
                    if not self.stop:
                        self.id_played.emit(arg, got if isinstance(got, dict) else None)
                else:
                    self._skip_to(*arg)
            except Exception:                            # noqa: BLE001
                pass
        with self._lock:
            self._doing_busy = False

    def request_suggest(self, artist_uri: str) -> None:
        with self._lock:
            self._suggest = artist_uri or ""

    def request_discover(self) -> None:
        with self._lock:
            self._discover = True

    def request_catsearch(self, q: str) -> None:
        """Spotify catalogue search on a thread of its own; a newer query
        replaces one in flight."""
        with self._lock:
            self._search = q
            if self._search_busy:
                return
            self._search_busy = True
        threading.Thread(target=self._catsearch_loop, daemon=True).start()

    def _catsearch_loop(self) -> None:
        while not self.stop:
            with self._lock:
                q, self._search = self._search, None
                if q is None:
                    self._search_busy = False
                    return
            got = self._catsearch(q)
            if not self.stop:
                self.catsearch_ready.emit(q, got)
        with self._lock:
            self._search_busy = False

    def request_gsearch(self, q: str) -> None:
        """On a thread of its own, for the same reason as _warm: this is a
        request to Genius over the network with seconds of timeout behind it,
        and the fetcher's own loop is what answers the track that is playing.
        A query typed while one is out replaces it; see _gsearch_loop."""
        with self._lock:
            self._gsearch = q
            if self._gsearch_busy:
                return
            self._gsearch_busy = True
        threading.Thread(target=self._gsearch_loop, daemon=True).start()

    def _gsearch_loop(self) -> None:
        while not self.stop:
            with self._lock:
                q, self._gsearch = self._gsearch, None
                if q is None:
                    self._gsearch_busy = False
                    return
            got = self._genius_search(q)
            if not self.stop:
                self.gsearch_ready.emit(q, got)
        with self._lock:
            self._gsearch_busy = False

    def request_gmatch(self, hit: dict) -> None:
        with self._lock:
            self._gmatch = dict(hit or {})

    def request_ahead(self, rows, sources, order, people=None) -> None:
        """Warm the cache for tracks that are coming up. See _warm.

        Cheap where there is nothing to do: a track whose answer is already on
        disk costs the walk one stat and no round trip, so this can be handed
        the same three tracks every minute without spending anything on them.
        """
        with self._lock:
            if people is not None:
                self._people = people
            self._ahead = [(str(tid), dict(meta), set(sources), list(order))
                           for tid, meta in (rows or []) if tid]
            self._ahead_gen += 1
            if not self._ahead:
                return
        t = self._ahead_thread
        if t is None or not t.is_alive():
            t = threading.Thread(target=self._warm, name="lyrics-ahead",
                                 daemon=True)
            self._ahead_thread = t
            t.start()

    def _warm(self) -> None:
        """The coming tracks' picks, made ahead by the load's own code on a
        thread of its own, asking the widest question. See lyrics_gui.md
        (2026-10-24)."""
        waited = 0.0
        while not self.stop:
            with self._lock:
                if not self._ahead:
                    return
                gen, rule = self._ahead_gen, self._people
                job = None if self._busy() else self._ahead.pop(0)
            if job is None:
                if waited >= WARM_PATIENCE:
                    with self._lock:
                        if self._ahead_gen == gen:
                            self._ahead = []
                    return
                waited += WARM_LOOK
                time.sleep(WARM_LOOK)
                continue
            waited = 0.0
            tid, meta, want, order = job
            if not want or not str(meta.get("title") or "").strip():
                continue
            sid = str(meta.get("_spotify", "") or "")
            meta = {k: v for k, v in meta.items() if k != "_spotify"}
            lines, whole = self._pick_ahead(tid, meta, want, order, rule, sid)
            if lines and tid not in self._ahead_told:
                # For LayoutAhead and roman_ahead, once a track: the lines the load will show.
                self._ahead_told[tid] = True
                if len(self._ahead_told) > 64:
                    self._ahead_told.pop(next(iter(self._ahead_told)))
                self.ahead_ready.emit(tid, copy.deepcopy(lines))
            with self._lock:
                if (not whole and self._busy()
                        and self._ahead_gen == gen):
                    self._ahead.insert(0, job)

    def _pick_ahead(self, tid: str, meta: dict, want, order, rule, sid: str = ""):
        """A coming song's pick, made by _load_words itself off the screen and kept for its
        load (_kept_pick). (lines, whole): whole is False when the walk was cut short or a
        source failed, and then nothing is kept -- the load decides as it always did."""
        alive = lambda: not self.stop and not self._busy()      # noqa: E731
        with self._lock:
            same = set(want) == self._sources and list(order) == self._order
        if not same:            # the fetcher has not been handed these settings yet: warm only
            if sid and "spicy" in want and sid != tid:
                try:
                    LS.spicy_lyrics(sid)
                except Exception:                            # noqa: BLE001
                    pass
            try:
                got = LS.fallback(tid, meta, "none", enabled=want, order=order,
                                  people=rule, alive=alive)
                return (SL.timeline(got[0], split=self.split, threshold=self.threshold)
                        if got else []), False
            except Exception:                            # noqa: BLE001
                return [], False
        here = self._here
        here.no, here.meta, here.rule = None, dict(meta), rule.fork()
        here.quiet, here.sid, here.flawed = True, sid, False
        key = self._pick_key(tid)
        try:
            lines, body = self._load_words(tid)
        except Exception:                                # noqa: BLE001
            lines, body, here.flawed = [], None, True
        finally:
            here.quiet = False
        whole = not here.flawed and alive() and key == self._pick_key(tid)
        if whole and lines:
            ids = tuple(dict.fromkeys(i for i in (tid, sid) if i))
            kept = (key, lines, body, mono(), ids, here.rule.met(), _pick_names(meta))
            with self._lock:
                for i in ids:
                    self._picks[i] = kept
                while len(self._picks) > 16:
                    self._picks.pop(next(iter(self._picks)))
        return lines, whole

    def _pick_key(self, tid: str) -> tuple:
        """Everything _load_words decides a song's pick under, to tell a pick made ahead
        from one the settings have moved on from since."""
        with self._lock:
            mine = (tuple(sorted(self._sources)), tuple(self._order), self._graft,
                    self._fold, self._clean, self._people.key())
        return mine + (LS.bases_key(), LS.syncs_key(), LS.song_pick(tid),
                       self.split, self.threshold, bool(self.spotify_lookup))

    def _kept_pick(self, tid: str):
        """The pick _pick_ahead made for this song, once, while the settings it was made
        under still hold; None otherwise."""
        with self._lock:
            got = self._picks.get(tid)
            for i in got[4] if got else ():
                self._picks.pop(i, None)
        if got is None or mono() - got[3] > PICK_KEPT or got[0] != self._pick_key(tid) \
                or got[6] != _pick_names(self._song_meta()):     # asked ahead under other names (listen along's Deezer ones)
            return None
        rule = getattr(self._here, "rule", None)
        if rule is not None and got[5]:
            with rule._lock:
                rule._met.update(got[5])
        DH.TRACE.phase(tid, "ahead", DH.now())
        return got[1], got[2]

    def _busy(self) -> bool:
        """Whether a new track the user is waiting on needs the network now
        (not the one already on screen)."""
        return ((self._loading is not None and self._loading != self._loaded)
                or (self._want is not None and self._want != self._loaded))

    def request_backfill(self, ids) -> None:
        with self._lock:
            self._backfill_ids = list(ids)
            self._backfill_at = 0

    def request_genius(self, token, tid, title, artist, ours,
                       asides=(), texts=()) -> None:
        with self._lock:
            self._genius = (token, tid, title, artist, ours, set(asides),
                            list(texts))

    def request_roman_ahead(self, tid: str, meta: dict, token: str, ours: list, asides,
                            texts: list, all_texts: list, readings: list) -> None:
        """A coming song's romanisation, Genius's and NetEase's, asked while this one plays
        (see the window's roman_ahead); answered on roman_ahead_ready, once each."""
        with self._lock:
            self._roman_ahead.append((tid, dict(meta), token, list(ours), set(asides), list(texts),
                                      list(all_texts), list(readings)))
            t = self._roman_thread
            if t is None or not t.is_alive():
                t = self._roman_thread = threading.Thread(target=self._romans, name="roman-ahead",
                                                          daemon=True)
                t.start()

    def _romans(self) -> None:
        """request_roman_ahead's asks, one at a time, never while a song is being loaded:
        the song the reader is waiting on comes first, as for _warm."""
        while not self.stop:
            with self._lock:
                job = None if self._busy() else (self._roman_ahead.pop(0) if self._roman_ahead else None)
                left = bool(self._roman_ahead)
            if job is None:
                if not left:
                    return
                time.sleep(WARM_LOOK)
                continue
            tid, meta, token, ours, asides, texts, all_texts, readings = job
            mapping = None
            if token:
                try:
                    got = GR.find_romanisation(token, meta.get("title", ""), meta.get("artist", ""),
                                               texts=texts)
                    if got:
                        mapping = offload.call(GR.align, ours, got[0], 0.55, GR.MAX_JOIN, tuple(asides))
                except Exception:                            # noqa: BLE001
                    mapping = None
            try:
                ne = GR.fit_pairs(LS.netease_roman(meta), all_texts, readings)
            except Exception:                                # noqa: BLE001
                ne = {}
            if not self.stop:
                self.roman_ahead_ready.emit(tid, mapping, ne)

    def request_ne_roman(self, tid: str, meta: dict, texts: list,
                         readings: list) -> None:
        with self._lock:
            self._ne_roman = (tid, dict(meta or {}), list(texts),
                              list(readings))

    def request_apple(self, tid: str, meta: dict) -> None:
        """Apple Music's sync, to save in place of a community one."""
        with self._lock:
            self._apple = (tid, dict(meta or {}))
        self._chores.set()

    def request_album(self, uri: str, kind: str = "album") -> None:
        with self._lock:
            self._album = (uri, kind) if uri else None

    def run(self) -> None:
        """Lyric requests only, each walk on its own thread; a repeat ask
        during a walk is remembered and run once it ends."""
        while not self.stop:
            with self._lock:
                tid, self._want = self._want, None
                self._wake.clear()
                due = tid is not None and self._pending.get(tid, 0) <= mono()
                if tid and not due:
                    if self._want is None:
                        self._want = tid
                    tid = None
                elif tid and self._walk_live and self._walk_tid == tid:
                    self._walk_again = True
                    tid = None
                if tid:
                    self._walk_no += 1
                    no, asked = self._walk_no, tid in self._pending
                    meta = dict(self._meta)
                    if tid != self._walk_tid:
                        # A new visit stands in its stored copy again, even
                        # when the walk between was overtaken too soon to
                        # set _stood_in -- A, B, straight back to A.
                        self._stood_in = None
                    self._walk_tid, self._walk_live = tid, True
                    self._walk_again = False
                    self._loading = tid
                waiting = bool(self._pending)
            if tid:
                threading.Thread(target=self._walk, args=(tid, no, asked, meta),
                                 name="lyrics-walk", daemon=True).start()
            self._wake.wait(POLL_WAITING if waiting else POLL_IDLE)

    def _walk(self, tid: str, no: int, asked: bool, meta: dict) -> None:
        """One track's lyric walk, start to finish; an overtaken walk still
        reports but does not set the screen's state."""
        self._here.no, self._here.meta = no, meta
        with self._lock:
            self._here.rule = rule = self._people.fork()
        lines, body = [], None
        try:
            lines, body = self._load(tid, settled=asked)
        finally:
            with self._lock:
                current = no == self._walk_no
                if current:
                    self._loading, self._loaded = None, tid
                    self._walk_live = False
                # A settled walk that found nothing is the answer (instrumental,
                # or nobody has it): no retry, and no re-ask queued behind it.
                final = bool(lines) or (current and asked)
                if final:
                    self._pending.pop(tid, None)
                    self._backoff.pop(tid, None)
                elif current:
                    step = self._backoff.get(tid)
                    step = RETRY_FIRST if not step else min(RETRY_MAX, step * 2)
                    self._backoff[tid] = step
                    self._pending[tid] = mono() + step
                again = current and (self._walk_again or not final)
                if again and self._want is None:
                    self._want = tid
            if current and (asked or lines):
                self.done = tid
            if again:
                self._wake.set()
        if self.stop:
            return
        if body and current:
            self._shown = (tid, LS.RANK.get(LS.quality(body), 0))
        self.ready.emit(tid, lines, body)
        met = rule.met()
        if current and met and not self.stop:
            self.people_met.emit(tid, met)
        if current and not self.stop:
            self.artists_ready.emit(tid, self._artists(tid))

    def serve(self) -> None:
        """Everything the fetcher does that is not a lyric walk. See run()."""
        while not self.stop:
            with self._lock:
                want_index, self._index = self._index, False
                gen, self._genius = self._genius, None
                ne_rom, self._ne_roman = self._ne_roman, None
                apple, self._apple = self._apple, None
                card, self._card = self._card, None
                album, self._album = self._album, None
                recents, self._recents = self._recents, False
                want_q, self._queue = self._queue, False
                sugg, self._suggest = self._suggest, None
                disc, self._discover = self._discover, False
                gmatch, self._gmatch = self._gmatch, None
                self._chores.clear()
            if gen and not self.stop:
                self._genius_lookup(*gen)
            if album and not self.stop:
                a_uri, a_kind = album
                js = JS_ARTIST if a_kind == "artist" else JS_ALBUM
                got = self._eval(js % json.dumps(a_uri))
                if isinstance(got, dict):
                    got["art"] = art_url(got.get("art") or "")
                self.album_ready.emit(a_uri, got)
            if card and not self.stop:
                tid_c, meta_c = card
                try:
                    got = LS.track_card(meta_c)
                except Exception:                            # noqa: BLE001
                    got = {}
                if not self.stop:
                    self.card_ready.emit(tid_c, got)
            if ne_rom and not self.stop:
                tid_r, meta_r, texts_r, reads_r = ne_rom
                try:
                    got = GR.fit_pairs(LS.netease_roman(meta_r), texts_r,
                                       reads_r)
                except Exception:
                    got = {}
                if not self.stop:
                    self.ne_roman_ready.emit(tid_r, got)
            if apple and not self.stop:
                self.apple_ready.emit(apple[0], LS.apple_instead(*apple))
            if recents and not self.stop:
                self.recents_ready.emit(*self._recents_fetch())
            if want_q and not self.stop:
                self.queue_ready.emit(self._queue_fetch())
            if sugg is not None and not self.stop:
                self.suggest_ready.emit(self._suggest_fetch(sugg))
            if disc and not self.stop:
                self.discover_ready.emit(self._discover_fetch())
            if gmatch is not None and not self.stop:
                self.gmatch_ready.emit(gmatch, self._genius_match(gmatch))
            if self._backfill_at is not None and not self.stop:
                self._backfill_batch()
            if want_index and self._index_at is None:
                self._index_at, self._index_songs = 0, []
            if self._index_at is not None:
                self._index_batch()
            self._chores.wait(POLL_IDLE)

    def _genius_lookup(self, token, tid, title, artist, ours,
                       asides=(), texts=()) -> None:
        """Network + alignment, both off the GUI thread."""
        try:
            got = GR.find_romanisation(token, title, artist, texts=texts)
        except Exception:
            got = None
        if not got:
            self.genius_ready.emit(tid, None, None)
            return
        lines, hit = got
        try:
            # Out of process where there is a pool: up to 1.3s of the GIL.
            mapping = offload.call(GR.align, ours, lines, 0.55, GR.MAX_JOIN,
                                   tuple(asides))
        except Exception:
            mapping = {}
        self.genius_ready.emit(tid, mapping, hit.get("full_title") or "")

    def _alive(self, tid: str, no: int | None = None) -> bool:
        """Whether anybody still waits on this track's walk: a different id in
        the slot means skipped (an empty slot is told by `_mine`)."""
        if self.stop or not self._mine(no):
            return False
        with self._lock:
            return self._want is None or self._want == tid

    def _mine(self, no: int | None = None) -> bool:
        """Whether walk `no` (the caller's by default) is the newest; True off
        a walk."""
        if getattr(self._here, "quiet", False):
            return False                            # a pick made ahead (_pick_ahead) shows nothing
        if no is None:
            no = getattr(self._here, "no", None)
        return no is None or no == self._walk_no

    def _song_meta(self) -> dict:
        """The track's details as they were when its walk began.

        Not the slot's: request() overwrites that with the next song's the
        moment the user skips, while this walk may still be uncensoring or
        asking about a duet under ITS track's id.
        """
        meta = getattr(self._here, "meta", None)
        if meta is None:
            with self._lock:
                meta = self._meta
        return dict(meta)

    def _conn(self):
        """The page connection, made under the lock if absent; connect()'s
        SystemExit turned back into a failure."""
        with self._lock:
            cdp = self.cdp
        if cdp is not None:
            return cdp
        try:
            made = connect(self.port)
        except SystemExit as exc:
            raise ConnectionError(str(exc) or "no page to connect to") from exc
        with self._lock:
            if self.cdp is None:
                self.cdp = made
                return made
            cdp = self.cdp
        made.close()
        return cdp

    def _drop(self, cdp=None) -> None:
        """Let go of the page connection after any failed call, since a
        timed-out read leaves the socket mid-frame."""
        with self._lock:
            if cdp is not None and self.cdp is not cdp:
                return
            gone, self.cdp = self.cdp, None
        try:
            if gone:
                gone.close()
        except Exception:                                # noqa: BLE001
            pass

    def _ask(self, js):
        """One evaluation in the page, or None -- and never a bad socket left up.

        None means "no answer", which is all every caller here does with it.
        """
        cdp = None
        try:
            cdp = self._conn()
            return cdp.evaluate(js)
        except Exception:                                # noqa: BLE001
            self._drop(cdp)
            return None

    def _eval(self, js):
        return self._ask(js)

    def page_eval(self, js):
        """One evaluation in the page for a plugin (api.spotify): the value,
        or the failure itself rather than _ask's None. A script that threw
        leaves the socket as good as it was; anything else drops it, as
        _ask does."""
        cdp = self._conn()
        try:
            return cdp.evaluate(js)
        except RuntimeError:
            raise
        except Exception:                                # noqa: BLE001
            self._drop(cdp)
            raise

    def _index_batch(self) -> None:
        """One page of the on-disk lyrics per call, for the index, so lyric
        requests keep being served."""
        batch = LS.spicy_page(self._index_at, 100)
        if not batch:
            songs, self._index_songs, self._index_at = self._index_songs, [], None
            if not self.stop:
                self.index_ready.emit(songs)
            return
        for e in batch:
            try:
                doc = SL.payload(e["body"])
                lines = [t for t in (SL.line_text(i) for i in
                                     (doc.get("Content") or doc.get("Lines") or [])
                                     if isinstance(i, dict)) if t and t.strip()]
                if lines:
                    items = doc.get("Content") or doc.get("Lines") or []
                    synced = any(isinstance(i, dict) and isinstance(i.get("Lead"), dict)
                                 and (i["Lead"].get("Syllables") or [])
                                 for i in items)
                    roman = bool(doc.get("HasTransliterations"))
                    self._index_songs.append({"id": e["id"], "lines": lines,
                                              "synced": synced, "roman": roman,
                                              "lang": doc.get("Language") or "",
                                              "title": "", "artist": ""})
            except Exception:
                continue
        self._index_at += len(batch)
        if not self.stop:
            self.index_progress.emit(len(self._index_songs))

    def _recents_fetch(self):
        n = 24
        got = self._eval(JS_RECENTS % (n, n, n)) or {}
        tracks = [t for t in (got.get("tracks") or []) if isinstance(t, dict)]
        ctx = [c for c in (got.get("ctx") or []) if isinstance(c, dict)]
        for row in tracks + ctx:
            row["art"] = art_url(row.get("art") or "")
        return tracks, ctx

    def _skip_to(self, uri: str, uid: str) -> None:
        """Jump to an item already in the queue.

        skipTo takes the queue entry, so the uid matters -- the same track can
        legitimately sit in the queue more than once. If the shape is ever
        rejected, playing the uri outright is a worse but working answer.
        """
        js = ("(async () => { try {"
              "  await Spicetify.Platform.PlayerAPI.skipTo(%s); return true;"
              "} catch (e) { try { Spicetify.Player.playUri(%s); } catch (e2) {}"
              "  return false; } })()")
        self._eval(js % (json.dumps({"uri": uri, "uid": uid}), json.dumps(uri)))

    def _queue_fetch(self):
        got = self._eval(JS_QUEUE)
        if not isinstance(got, dict):
            return None
        items = [r for r in (got.get("items") or []) if isinstance(r, dict)]
        for r in items:
            r["art"] = art_url(r.get("art") or "")
        cur = got.get("current")
        if isinstance(cur, dict):
            cur["art"] = art_url(cur.get("art") or "")
        return {"current": cur if isinstance(cur, dict) else None, "items": items}

    def _suggest_fetch(self, artist_uri: str):
        got = self._eval(JS_SUGGEST % json.dumps(artist_uri or ""))
        if not isinstance(got, dict):
            return None
        out = {}
        out["artist"] = str(got.get("artist") or "")
        for key in ("related", "playlists", "top", "mine"):
            rows = [r for r in (got.get(key) or []) if isinstance(r, dict) and r.get("uri")]
            for r in rows:
                r["art"] = art_url(r.get("art") or "")
            out[key] = rows
        return out

    def _discover_fetch(self):
        """Up to eight round trips, so it runs on its own request rather than
        holding up the artist shelves that come back in one."""
        cur = self._eval(
            '(() => { try { const d = Spicetify.Player.data,'
            ' it = d && (d.item || d.track);'
            ' return (((it || {}).artists || [])[0] || {}).uri || ""; }'
            ' catch (e) { return ""; } })()') or ""
        got = self._eval(JS_DISCOVER % json.dumps(cur))
        if not isinstance(got, dict):
            return None
        out = {"seed": str(got.get("seed") or "")}
        for key in ("because", "songs"):
            rows = [r for r in (got.get(key) or []) if isinstance(r, dict) and r.get("uri")]
            for r in rows:
                r["art"] = art_url(r.get("art") or "")
            out[key] = rows
        return out

    def _catsearch(self, query: str):
        """Spotify's catalogue. Returns [] rather than raising when the shape
        drifts, so the screen says 'no results' instead of blanking."""
        if len(query) < 2:
            return []
        got = self._eval(JS_SEARCH % json.dumps(query))
        if not isinstance(got, list):
            return []
        rank = {"Track": 0, "Album": 1, "Artist": 2}
        label = {"Track": "Songs", "Album": "Albums", "Artist": "Artists"}
        out = []
        for r in got:
            if not isinstance(r, dict) or not r.get("uri"):
                continue
            r["art"] = art_url(r.get("art") or "")
            r["section"] = label.get(r.get("kind") or "", "On Spotify")
            out.append(r)
        out.sort(key=lambda r: rank.get(r.get("kind") or "", 3))
        return out

    def _genius_search(self, query: str):
        """Genius's own lyric search, for the words that are in no cached song.

        The index only knows songs whose lyrics are already on this machine,
        so half-remembered lines from songs never played here found nothing.
        Genius searches the words themselves and needs no token for it.
        """
        try:
            return GR.search_lyrics(query, load_token(), limit=6)
        except Exception:
            return []

    def _genius_match(self, hit: dict):
        """The Spotify track a Genius hit is about, or None below the match
        floor."""
        raw = (hit.get("title") or "").strip()
        title = re.sub(r"[\(\[\{].*?[\)\]\}]", "", raw).strip() or raw
        artist = (hit.get("artist") or "").strip()
        if GR.GENIUS_ACCOUNT.search(artist):
            artist = ""
        if not title:
            return None
        rows = self._catsearch(f"{title} {artist}".strip()) or []
        best, score = None, 0.0
        for r in rows:
            if r.get("kind") != "Track" or not r.get("uri"):
                continue
            s = 0.65 * GR.similar(title, r.get("name") or "")
            s += 0.35 * (GR.similar(artist, r.get("sub") or "") if artist else 0.35)
            if s > score:
                best, score = r, s
        if best is None or score < 0.45:
            return None
        return dict(best, score=round(score, 3))

    def _backfill_batch(self) -> None:
        at, ids = self._backfill_at, self._backfill_ids
        if at is None or at >= len(ids):
            self._backfill_at = None
            if not self.stop:
                self.backfill_ready.emit(None)
            return
        chunk = ids[at:at + 25]
        got = [r for r in (self._eval(JS_TRACKS % json.dumps(chunk)) or []) if isinstance(r, dict)]
        named = {r.get("id") for r in got if r.get("name")}
        import stream_source as SS
        for tid in chunk:
            # Spotify away, or no name from it: its public embed page, no app needed (2026-10-25)
            if tid in named or self.stop or not (len(tid) == 22 and tid.isalnum()):
                continue
            try:
                e = SS._embed("track", tid)
            except Exception:
                continue
            if e.get("name"):
                got.append({"id": tid, "name": e["name"], "artist": ", ".join(
                    a.get("name", "") for a in e.get("artists") or [] if a.get("name"))})
        self._backfill_at = at + len(chunk)
        if self.stop:
            return
        self.backfill_ready.emit(got)
        self.backfill_progress.emit(self._backfill_at, len(ids))

    def _artists(self, tid: str):
        """Everyone credited on the track, as the page has it."""
        if self.cdp is None:
            return None
        return self._ask(JS_ARTISTS % json.dumps(tid))

    def _audio(self, tid: str, wait_ms: int = BEAT_WAIT_MS):
        """Audio analysis in one round trip (`wait_ms` for the page), dialling
        if there is no socket; asked from `_beat_for`'s thread."""
        return self._ask(Beat.JS % (json.dumps(f"spotify:track:{tid}"), wait_ms))

    def _grab_spotify_token(self) -> None:
        """Keep the desktop app's access token while Spotify is open (only with
        Spotify lookup on), renewed within ten minutes of expiry."""
        if not self.spotify_lookup or LS.spotify_session_left() > 600:
            return
        try:
            got = self._eval(JS_TOKEN)
        except Exception:                                   # noqa: BLE001
            return
        if isinstance(got, dict) and got.get("t"):
            LS.keep_spotify_session(str(got["t"]), float(got.get("exp") or 0))

    def _spotify_id(self, tid: str) -> str | None:
        """The Spotify track a non-Spotify player's song is, or None: name,
        artist and length within four seconds. Only with Spotify lookup on."""
        if tid in self._sid_cache:
            return self._sid_cache[tid]
        known = LS.spotify_id_known(tid)
        if known:
            self._sid_cache[tid] = known
            return known
        self._grab_spotify_token()
        meta = self._song_meta()
        if not meta.get("title"):
            return None
        try:
            card = LS.apple_card(meta)
        except Exception:                                   # noqa: BLE001
            card = {}
        metas = [dict(meta)]
        if card.get("sure"):
            named = dict(meta)
            named.update({k: card[k] for k in ("title", "artist", "length")
                          if card.get(k)})
            if named != meta:
                metas.insert(0, named)
        answered, found = False, None
        for m in metas:
            for ask in (lambda: self._catsearch(
                            f"{m['title']} {m.get('artist') or ''}".strip()),
                        lambda: LS.spotify_web_search(m)):
                try:
                    rows = ask()
                except Exception:                           # noqa: BLE001
                    rows = None
                if not rows:
                    continue
                answered = True
                found = _spotify_match(rows, m)
                if found:
                    break
            if found:
                break
        if found:
            LS.spotify_id_keep(tid, found)
        if found or answered:
            if len(self._sid_cache) > 512:
                self._sid_cache.clear()
            self._sid_cache[tid] = found
        return found

    def _spicy_body(self, tid: str):
        """Spicy Lyrics' copy of a track and whether the service answered: None
        with reached=True is final; reached=False falls through to the
        chain."""
        try:
            body = LS.spicy_lyrics(tid)
            return (None if LS.wordless(body) else body), True
        except LS.SpicyError as exc:
            if getattr(self._here, "quiet", False):
                self._here.flawed = True
            elif not exc.temporary:
                self.source_trouble.emit(tid, [("spicy", str(exc))])
            return None, False

    def _load(self, tid: str, settled: bool = True):
        """_load_words, timed for the debug overlay; see debug_hud."""
        DH.TRACE.begin(tid)
        lines, body = [], None
        try:
            lines, body = self._load_words(tid, settled)
        finally:
            said = SL.payload(body or {}) if body else {}
            src = str(said.get("_source") or "")
            if src == "bini" and said.get("_door") == "lrc.red":
                src = "lrc.red"
            DH.TRACE.end(tid, src, LS.quality(body) if body else "none",
                         len(lines or ()))
        return lines, body

    def _load_words(self, tid: str, settled: bool = True):
        """The song's words: Spicy Lyrics first, then the chain when its answer
        is thin; never asked twice."""
        with self._lock:
            spicy = "spicy" in self._sources
            none_on = not self._sources
            order, graft = list(self._order), self._graft
            rule = getattr(self._here, "rule", None) or self._people
        ahead = order[:order.index("spicy")] if "spicy" in order else []
        if none_on:
            if self._mine():
                self._stood_in = tid
            return [], None
        quiet = getattr(self._here, "quiet", False)
        kept = None if quiet else self._kept_pick(tid)
        if kept is not None:
            return kept
        if LS.instrumental_cut(str(self._song_meta().get("title") or "")):
            return [], None
        pick = LS.song_pick(tid)
        if pick and pick != "spicy":
            doc = self._picked(tid, self._song_meta(), pick)
            if doc is not None:
                return self._finished(tid, doc)
        if self._stood_in != tid and self._mine():
            self._stood_in = tid
            was = LS.stored(tid)
            if was and not rule.blocks(was):
                self._interim(tid, was)
        if not spicy:
            return self._only_fallback(tid)
        sid, began = tid, DH.now()
        if not SONG_KEY.fullmatch(tid or "") and not quiet:
            self._grab_spotify_token()
        if SONG_KEY.fullmatch(tid or ""):
            # One found ahead (stream_source keep_for_lyrics) is used whatever the lookup
            # setting: it came from public sources, not a search through the reader's Spotify.
            if quiet:           # ahead: no search through the page, which is the load's
                sid = self._here.sid or LS.spotify_id_known(tid)
                if not sid and self.spotify_lookup:
                    self._here.flawed = True        # the load may yet find one
            else:
                sid = self._spotify_id(tid) if self.spotify_lookup else LS.spotify_id_known(tid)
            DH.TRACE.phase(tid, "id", began)
            if not sid:
                return self._only_fallback(tid)
        else:
            DH.TRACE.phase(tid, "id", began)
        began = DH.now()
        body, reached = self._spicy_body(sid)
        DH.TRACE.asked(tid, "spicy", DH.now() - began, body,
                       "" if reached else "unreachable")
        if not reached:
            return self._only_fallback(tid)
        refused = bool(body) and (rule.blocks(body) or LS.sync_off("spicy", body))
        if refused:
            body = None
        have = LS.quality(body) if body else "none"
        ahead = LS.ahead_of("spicy", have, order)
        shaped = None
        if body:
            began = DH.now()
            shaped = self._shaped(body)
            DH.TRACE.phase(tid, "shape", began)
            self._interim(tid, shaped, shaped=True)
        elif self._stood_in != tid and self._mine():
            self._stood_in = tid
            was = LS.stored(tid)
            self._interim(tid, None if rule.blocks(was) else was)
        liked = rule.likes(body)
        if liked:
            ahead = []
        hunt = bool(rule.pick) and not liked
        better = None
        if (have != "syllable" or ahead or hunt) and (body or settled) and not (pick == "spicy" and body):
            better = self._fallback(tid, have, ahead, local=body)
        if better is not None:
            merged = None
            whose = str(better.get("_alone") or better.get("_source") or "")
            if whose == "netease" and graft and _above(order, "spicy", "netease"):
                merged = LS.graft_syllables(body, better)
            body = merged if merged is not None else better
            shaped = None
        if not body:
            return [], None
        return self._finished(tid, body, shaped)

    def _shaped(self, body):
        """The document as drawn: unlumped, with the ad-lib repair only where
        LS.needs_adlibs says the ad-libs are still in the lyric."""
        with self._lock:
            fold = self._fold and LS.needs_adlibs(body)
        if fold:
            body = LS.fold_cries(body)
        body = LS.unlump(body)
        if LS.lrc_shaped(body):
            body = LS.close_holes(body)
        body = LS.quiet_marks(body)
        if fold:
            body = LS.split_asides(body)
        return LS.no_overlap(body)

    def _uncensored(self, tid: str, body):
        """The letters a clean edit masked put back, after _shaped; the same
        object when nothing changed. Never on the interim."""
        meta = self._song_meta()
        with self._lock:
            want, on = set(self._sources), self._clean
        if not on:
            return body

        def kept(why: str) -> None:
            with self._lock:
                self._kept[tid] = why

        with self._lock:
            self._kept.pop(tid, None)
        try:
            return LS.uncensor(body, tid, meta, enabled=want, on_skip=kept)
        except Exception:                                # noqa: BLE001
            return body

    def masks_kept(self, tid: str) -> str:
        """Why this track's masks were left as they were, or ""."""
        with self._lock:
            return self._kept.get(tid, "")

    def _interim(self, tid: str, body, shaped: bool = False,
                 no: int | None = None) -> None:
        """Show a document now while a better one is sought (no _duet); never
        backwards from what is shown, and only from the newest walk.
        `shaped` if done already."""
        if not body or self.stop or not self._mine(no):
            return
        rank = LS.RANK.get(LS.quality(body), 0)
        was_tid, was_rank = self._shown
        if tid == was_tid and rank < was_rank:
            return
        if not shaped:
            body = self._shaped(body)
        try:
            lines = SL.timeline(body, split=self.split, threshold=self.threshold)
        except Exception:
            return
        if lines and not self.stop:
            self._shown = (tid, rank)
            DH.TRACE.shown(tid)
            self.ready.emit(tid, lines, body)

    def _duet(self, tid: str, lines: list) -> None:
        """Fill in a duet's second voice when the source forgot to mark it."""
        meta = self._song_meta()
        with self._lock:
            want = set(self._sources)
        try:
            flags = LS.duet_flags(lines, tid, meta, enabled=want)
        except Exception:
            return
        for ln, on in zip(lines, flags or []):
            ln["opposite"] = on

    def _only_fallback(self, tid: str):
        """Spicy Lyrics switched off: whatever the rest of the chain has.

        Shaped like any other answer. With Spicy Lyrics off this is where
        NetEase, QQ Music and Kugou documents actually reach the screen, and
        they are the ones whose ad-libs need putting back.
        """
        body = self._fallback(tid, "none")
        if not body:
            return [], None
        return self._finished(tid, body)

    def preview_body(self, tid: str, meta: dict):
        """(document, source) a song not playing would show if it played -- _load_words'
        picks and shaping, without touching the screen. None when nothing has it."""
        with self._lock:
            want, order, graft = set(self._sources), list(self._order), self._graft
            rule, clean = self._people, self._clean
        if not want or LS.instrumental_cut(str(meta.get("title") or "")):
            return None
        pick = LS.song_pick(tid)
        body = self._picked(tid, meta, pick) if pick and pick != "spicy" else None
        mine = body is not None
        if not mine and "spicy" in want and tid and not SONG_KEY.fullmatch(tid):
            try:
                body = LS.spicy_lyrics(tid)
                body = None if LS.wordless(body) or (body and (rule.blocks(body) or LS.sync_off("spicy", body))) \
                    else body
            except LS.SpicyError:
                body = None
        have = LS.quality(body) if body else "none"
        ahead = LS.ahead_of("spicy", have, order) if "spicy" in want else []
        liked = rule.likes(body)
        if liked:
            ahead = []
        if (have != "syllable" or ahead or (rule.pick and not liked)) and not (mine or (pick == "spicy" and body)):
            better = LS.fallback(tid, meta, have, enabled=want, order=order, ahead=ahead,
                                 local=body, people=rule, alive=lambda: not self.stop)
            if better is not None:
                whose = str(better.get("_alone") or better.get("_source") or "")
                merged = (LS.graft_syllables(body, better)
                          if whose == "netease" and graft and _above(order, "spicy", "netease") else None)
                body = merged if merged is not None else better
        if not body:
            return None
        said = SL.payload(body) or {}
        src = str(said.get("_source") or "spicy")
        body = self._shaped(body)
        if clean:
            try:
                body = LS.uncensor(body, tid, meta, enabled=want)
            except Exception:                            # noqa: BLE001
                pass
        return body, src

    @staticmethod
    def _picked(tid: str, meta: dict, name: str):
        """The source picked for this song on its Song page, asked alone; None when it has nothing
        now, and the usual walk decides."""
        fn = dict(LS.PROVIDERS).get(name)
        if fn is None:
            return None
        try:
            doc = LS._asks(name, lambda: fn(tid, meta), tid)
        except Exception:                                # noqa: BLE001
            return None
        if not isinstance(doc, dict) or LS.quality(doc) == "none":
            return None
        return {**doc, "_source": name}

    def shaped_copy(self, body):
        """Any source's document shaped as the screen would draw it (for comparing sources)."""
        try:
            return self._shaped(body)
        except Exception:                                # noqa: BLE001
            return body

    def _finished(self, tid: str, body, shaped=None):
        """The walk's pick, shaped, uncensored and laid out, each step timed
        for the debug overlay: the last two can go to the network."""
        began = DH.now()
        body = self._shaped(body) if shaped is None else shaped
        DH.TRACE.phase(tid, "shape", began)
        began = DH.now()
        body = self._uncensored(tid, body)
        DH.TRACE.phase(tid, "uncensor", began)
        try:
            lines = SL.timeline(body, split=self.split, threshold=self.threshold)
        except Exception:
            return [], None
        began = DH.now()
        self._duet(tid, lines)
        DH.TRACE.phase(tid, "duet", began)
        return lines, body

    def _fallback(self, tid: str, have: str, ahead=(), local=None):
        """Ask the other sources in order for something better than `have`,
        showing good answers as they land and reporting unreachable sources."""
        meta, no = self._song_meta(), getattr(self._here, "no", None)
        with self._lock:
            want = set(self._sources)
            order = list(self._order)
            rule = getattr(self._here, "rule", None) or self._people
        began = DH.now()
        if getattr(self._here, "quiet", False):     # ahead (_pick_ahead): nothing shown or said
            here = self._here

            report = None

            def alive():
                return not self.stop and not self._busy()

            def note(bad):
                here.flawed = True
        else:
            def alive():
                return self._alive(tid, no)

            def report(doc, _name):
                self._interim(tid, doc, no=no)

            def note(bad):
                self.source_trouble.emit(tid, bad)
        try:
            got = LS.fallback(tid, meta, have, enabled=want, order=order,
                              ahead=ahead, local=local, people=rule,
                              alive=alive, report=report, note=note)
        except Exception:
            return None
        finally:
            DH.TRACE.phase(tid, "walk", began)
        if not got:
            return None
        doc, name = got
        doc["_source"] = name
        return doc


# --------------------------------------------------------------------------
def render_pieces(ln: dict) -> list[tuple]:
    """Timed fragments to lay out and fill for one line; line-level text is
    split into words with interpolated times."""
    if ln["syls"]:
        return ln["syls"]
    words = ln["text"].split()
    s, e = ln["start"], ln["end"]
    if not words:
        return [(s, e, ln["text"], False)]
    if s is None or e is None or e <= s:
        return [(s, e, w, False) for w in words]
    total = sum(len(w) for w in words) or 1
    out, t = [], s
    for i, w in enumerate(words):
        end = e if i == len(words) - 1 else t + (e - s) * len(w) / total
        out.append((t, end, w, False))
        t = end
    return out


DASHES = "-\u2010\u2011\u2012\u2013\u2014"

PX_TOL = 0.03


def _flat_group(run: list[tuple], widths: list[float], i: int, j: int,
                tol: float, px: float) -> float | None:
    """How far run[i..j] drawn as one fragment strays from it drawn as many,
    judged at the corners by `px` or `tol`; the worst pixel error, or None."""
    s, e = run[i][0], run[j][1]
    span = e - s
    total = sum(widths[i:j + 1])
    if span <= 0 or total <= 0:
        return None
    worst, x = 0.0, 0.0
    for k in range(i, j + 1):
        a, b = run[k][0], run[k][1]
        if b < a:
            return None
        for t, at in ((a, x), (b, x + widths[k])):
            dx = abs(total * (t - s) / span - at)
            dt = abs(t - (s + span * at / total))
            if dt > tol and not (px > 0 and dx <= px):
                return None
            worst = max(worst, dx)
        x += widths[k]
    return worst


def _sung_core(core: str) -> str:
    """A piece without the punctuation at its ends: the part that is sung."""
    a, b = 0, len(core)
    while a < b and not core[a].isalnum():
        a += 1
    while b > a and not core[b - 1].isalnum():
        b -= 1
    return core[a:b]


def _join_flat(run: list[tuple], tol: float, width=None,
               px: float = PX_TOL) -> list[tuple]:
    """One word's syllables with the splits that do not change the fill taken
    out (drawn widths via `width`); spelled-out and markless-piece seams
    kept."""
    n = len(run)
    if n < 2:
        return run
    if any(y[0] is None or y[1] is None for y in run):
        return run
    cores = [y[2].strip() for y in run]
    if not sum(len(c) for c in cores):
        return run
    sung = [_sung_core(c) for c in cores]
    if width is None:
        widths = [float(len(c)) for c in sung]
        px = 0.0
    else:
        widths = [float(width(c)) if c else 0.0 for c in sung]
    walls = {k for k, (a, b) in enumerate(zip(cores, cores[1:]))
             if (a and a[-1] in DASHES) or (b and b[0] in DASHES)
             or not any(c.isalnum() for c in a)
             or not any(c.isalnum() for c in b)
             or any(c.isspace() for c in run[k][2])
             or any(c.isspace() for c in run[k + 1][2].rstrip())}
    best: list = [(0, 0.0, 0)] + [None] * n
    for j in range(1, n + 1):
        for i in range(j - 1, -1, -1):
            if i < j - 1 and i in walls:
                break
            if i == j - 1:
                err = 0.0
            else:
                err = _flat_group(run, widths, i, j - 1, tol, px)
                if err is None:
                    continue
            prev = best[i]
            cand = (prev[0] + 1, max(prev[1], err), i)
            if best[j] is None or cand[:2] < best[j][:2]:
                best[j] = cand
    groups, j = [], n
    while j:
        i = best[j][2]
        groups.append((i, j - 1))
        j = i
    out: list[tuple] = []
    for i, j in reversed(groups):
        if i == j:
            out.append(run[i])
        else:
            out.append((run[i][0], run[j][1],
                        "".join(y[2] for y in run[i:j + 1]), run[j][3]))
    return out


def merge_flat_splits(pieces: list[tuple], tol: float, width=None) -> list[tuple]:
    """Fragments with uninformative splits merged per word (see _join_flat);
    the same list when the setting is off."""
    if tol <= 0 or not pieces:
        return pieces
    out: list[tuple] = []
    run: list[tuple] = []
    for y in pieces:
        run.append(y)
        if not y[3]:
            out.extend(_join_flat(run, tol, width))
            run = []
    if run:
        out.extend(_join_flat(run, tol, width))
    return out


def _pieces_text(pieces) -> str:
    """Timed pieces back into the words they spell."""
    return "".join(t + ("" if part else " ") for _s, _e, t, part in pieces).strip()


def retime_roman(ln: dict, text: str, _thin: bool | None = None) -> list[tuple]:
    """Hang a replacement romanisation on the line's syllable timings, cut
    letter by letter where the syllable changes."""
    words = text.split()
    base = ln.get("syls_roman") or ln.get("syls") or []
    syls = ln.get("syls") or []
    if (ln.get("syls_roman") and len(syls) == len(base)
            and SL.CJK.search(str(ln.get("text") or ""))):
        # Read again where Genius says the dictionary guessed wrong (相 ai,
        # not sou), so there is a right guide to line its letters up with.
        fit = SL.fit_readings([y[2] for y in syls], [b[2] for b in base], text)
        base = [(b[0], b[1], r, b[3]) for b, r in zip(base, fit)]
    blank = {"syls": [], "text": text, "start": ln["start"], "end": ln["end"]}
    if not words or not base:
        return render_pieces(blank)

    aside = GR.asides(words, str(ln.get("text") or ""),
                      " ".join(t for _s, _e, t, _p in base))

    if _thin is None:
        if SL.script_of(str(ln.get("text") or "")) not in ("ar", "he"):
            return retime_roman(ln, text, False)
        plain = retime_roman(ln, text, False)
        thinned = retime_roman(ln, text, True)
        untimed = lambda got: sum(1 for pc in got if pc[0] is None)
        return thinned if untimed(thinned) < untimed(plain) else plain
    abjad = _thin

    def thin(k, idx):
        if not abjad:
            return k, idx
        keep = [(ch, i) for ch, i in zip(k, idx) if ch not in "aeiou"]
        if not keep:
            return k, idx
        return "".join(ch for ch, _i in keep), [i for _ch, i in keep]

    def keyed(w, word):
        return ("", []) if w in aside else thin(*GR.key_map(word))

    theirs, gword, gchar = [], [], []
    for w, word in enumerate(words):
        k, idx = keyed(w, word)
        theirs.append(k)
        gword.extend([w] * len(k))
        gchar.extend(idx)
    theirs = "".join(theirs)
    mine, syl = [], []
    for i, b in enumerate(base):
        k = GR.key(b[2])
        k = thin(k, range(len(k)))[0]
        mine.append(k)
        syl.extend([i] * len(k))
    mine = "".join(mine)
    if not theirs or not mine:
        return render_pieces(blank)

    at: list[int | None] = [None] * len(theirs)
    for a, b, size in SequenceMatcher(None, theirs, mine, autojunk=False).get_matching_blocks():
        for d in range(size):
            at[a + d] = b + d
    anchored = {gword[c] for c in range(len(theirs)) if at[c] is not None}
    owner: list[int | None] = [syl[p] if p is not None else None for p in at]
    claimed = {o for o in owner if o is not None}
    c0 = 0
    for w in range(len(words)):
        n = gword.count(w)
        span = range(c0, c0 + n)
        got = [owner[c] for c in span if owner[c] is not None]
        if got:
            head = got[0] - 1 if got[0] - 1 >= 0 and got[0] - 1 not in claimed \
                and (c0 == 0 or (owner[c0 - 1] or -1) < got[0] - 1) else got[0]
            tail = got[-1] + 1 if got[-1] + 1 < len(base) \
                and got[-1] + 1 not in claimed else got[-1]
            for c in span:
                if owner[c] is not None:
                    break
                owner[c] = head
            for c in reversed(span):
                if owner[c] is not None:
                    break
                owner[c] = tail
        c0 += n
    # Letters only Genius has, between two syllables of one word: a vowel,
    # the first of a doubled consonant or an ん close the syllable before
    # (tou|kyou, hak|ka); any other consonant opens the next (Ki|dzui).
    c = 0
    while not abjad and c < len(owner):
        if owner[c] is not None or not c:
            c += 1
            continue
        j = c
        while j < len(owner) and owner[j] is None:
            j += 1
        if (j < len(owner) and owner[c - 1] is not None
                and owner[c - 1] != owner[j] and gword[c - 1] == gword[j]):
            add, nxt = theirs[c:j], theirs[j]
            keep = (any(ch in "aeiou" for ch in add) or add[-1] == nxt
                    or (add == "n" and nxt not in "aeiouy")
                    or (add == "t" and theirs[j:j + 2] == "ch"))
            for d in range(c, j):
                owner[d] = owner[c - 1] if keep else owner[j]
        c = j
    last = None
    for c in range(len(owner)):
        if owner[c] is None:
            owner[c] = last
        else:
            last = owner[c]
    nxt = None
    for c in range(len(owner) - 1, -1, -1):
        if owner[c] is None:
            owner[c] = nxt
        else:
            nxt = owner[c]

    whole = GR.similar(theirs, mine) < 0.6
    atoms = []
    c = 0
    for w, word in enumerate(words):
        n = len(keyed(w, word)[0])
        if not n:
            atoms.append([w, word, None])
            continue
        cuts, s0 = [], c
        if whole:
            mid = (c + n / 2) / len(theirs)
            atoms.append([w, word, syl[min(len(syl) - 1, int(mid * len(syl)))]])
            anchored.add(w)
            c += n
            continue
        for d in range(n):
            if d and owner[c + d] != owner[c + d - 1]:
                cuts.append(d)
        hits = sum(1 for x in range(c, c + n) if at[x] is not None)
        if cuts and hits < 3 and hits * 2 < n:
            first = owner[c]
            others = {syl[at[x]] for x in range(len(at))
                      if at[x] is not None and gword[x] != w}
            span = [first] if first is not None else []
            while (span and span[-1] + 1 < len(base)
                   and span[-1] + 1 not in others
                   and sum(len(GR.key(base[k][2])) for k in span) < n):
                span.append(span[-1] + 1)
            if len(span) > 1:
                sizes = [max(1, len(GR.key(base[k][2]))) for k in span]
                tot, acc, d = sum(sizes), 0, 0
                for k, size in zip(span, sizes):
                    acc += size
                    upto = round(n * acc / tot)
                    while d < upto:
                        owner[c + d] = k
                        d += 1
                cuts = [x for x in range(1, n) if owner[c + x] != owner[c + x - 1]]
            else:
                cuts = []
        starts = [0] + cuts
        for j, d in enumerate(starts):
            lo = gchar[c + d] if d else 0
            hi = gchar[c + starts[j + 1]] if j + 1 < len(starts) else len(word)
            frag = word[lo:hi]
            if frag:
                atoms.append([w, frag, owner[c + d]])
        c += n

    out = []
    i = 0
    while i < len(atoms):
        j = i
        while (j + 1 < len(atoms) and atoms[j + 1][2] is not None
               and atoms[j + 1][2] == atoms[i][2]):
            j += 1
        run = atoms[i:j + 1]
        k = run[0][2]
        s, e = (base[k][0], base[k][1]) if k is not None else (None, None)
        if e is not None and s is not None and e < s:
            e = s
        timed_here = [a for a in run if a[0] in anchored]
        if len(timed_here) > 1 and s is not None and e is not None and e > s:
            total = sum(len(a[1]) for a in timed_here) or 1
            t = s
            left = len(timed_here)
            for a in run:
                if a[0] not in anchored:
                    out.append([None, None, a[0], a[1], k])
                    continue
                left -= 1
                nx = e if not left else t + (e - s) * len(a[1]) / total
                out.append([t, nx, a[0], a[1], k])
                t = nx
        else:
            for a in run:
                if a[0] in anchored:
                    out.append([s, e, a[0], a[1], k])
                else:
                    out.append([None, None, a[0], a[1], k])
        i = j + 1

    used = {o[4] for o in out if o[2] in anchored and o[4] is not None}
    i = 0
    while i < len(out):
        if out[i][2] in anchored:
            i += 1
            continue
        j = i
        while j + 1 < len(out) and out[j + 1][2] not in anchored:
            j += 1
        lo = max((o[4] for o in out[:i] if o[2] in anchored and o[4] is not None),
                 default=-1)
        hi = min((o[4] for o in out[j + 1:] if o[2] in anchored and o[4] is not None),
                 default=len(base))
        free = [x for x in range(lo + 1, hi) if x not in used]
        if free and all(base[x][0] is not None and base[x][1] is not None
                        for x in free):
            run = out[i:j + 1]
            letters = [(n, ch) for n, o in enumerate(run) for ch in o[3]]
            sizes = [max(1, len(GR.key(base[x][2]))) for x in free]
            tot, acc, cut, owner_of = sum(sizes), 0, [], []
            for x, size in zip(free, sizes):
                acc += size
                cut.append((round(len(letters) * acc / tot), x))
            at_syl, c_i = [], 0
            for L_i in range(len(letters)):
                while c_i < len(cut) - 1 and L_i >= cut[c_i][0]:
                    c_i += 1
                at_syl.append(cut[c_i][1])
            pieces = []
            for (n, ch), x in zip(letters, at_syl):
                if pieces and pieces[-1][0] == n and pieces[-1][1] == x:
                    pieces[-1][2] += ch
                else:
                    pieces.append([n, x, ch])
            fresh = []
            for x in free:
                here = [p_ for p_ in pieces if p_[1] == x]
                s0, e0 = base[x][0], base[x][1]
                tot_h = sum(len(p_[2]) for p_ in here) or 1
                t = s0
                for m, (n, _x, txt) in enumerate(here):
                    nx = e0 if m == len(here) - 1 else t + (e0 - s0) * len(txt) / tot_h
                    fresh.append([t, nx, run[n][2], txt, x])
                    t = nx
            out[i:j + 1] = fresh
            anchored |= {o[2] for o in run}
            j = i + len(fresh) - 1
        i = j + 1

    for i in range(1, len(out)):
        if out[i][0] is not None and out[i - 1][0] is not None and out[i][0] < out[i - 1][0]:
            out[i][0] = out[i - 1][0]
            out[i][1] = max(out[i][0], out[i][1] if out[i][1] is not None else out[i][0])
        if (out[i - 1][1] is not None and out[i][0] is not None
                and out[i - 1][1] > out[i][0]):
            out[i - 1][1] = max(out[i - 1][0], out[i][0])

    timed = {w for s, e, w, _, _ in out if s is not None} & anchored
    return [
        (s if w in timed else None, e if w in timed else None, txt,
         i + 1 < len(out) and out[i + 1][2] == w)
        for i, (s, e, w, txt, _) in enumerate(out)
    ]


def _level_of(chip, tab: str, level: str) -> str:
    """What the column marks one piece of the document with, by the review
    page's tab and `level` filters."""
    _marks, worst = chip.shows(tab)
    said = [m.level for m in _marks] + ([worst] if worst else [])
    if level:
        said = [x for x in said if x == level]
    for want in RV.LEVELS:
        if want in said:
            return want
    return ""


def _worst_told(rep, row, tab: str, level: str) -> str:
    """The heaviest thing the page would say about this line, under its filter."""
    for want in RV.LEVELS:
        if any(lv == want for lv, *_rest in rep.told(row, tab, level)):
            return want
    return ""


def prepare(lines: list[dict], min_gap: float, merge: float = 0.0,
            width=None) -> list[dict]:
    """Clamp open-ended lines and insert interlude markers. `merge` affects
    only the drawn pieces, never `syls`; `width` gives drawn widths."""
    for i, ln in enumerate(lines):
        if ln["end"] is None and ln["start"] is not None:
            nxt = next(
                (l["start"] for l in lines[i + 1:]
                 if l["start"] is not None and l["start"] > ln["start"]), None
            )
            ln["end"] = nxt if nxt is not None else ln["start"] + 4.0
        wide = None
        if width is not None:
            bg = bool(ln.get("background"))
            wide = lambda t, bg=bg: width(t, bg)
        ln["pieces"] = merge_flat_splits(render_pieces(ln), merge, wide)
        ln["pieces_roman"] = ln.get("syls_roman") or (
            render_pieces({"syls": [], "text": ln["text_roman"],
                           "start": ln["start"], "end": ln["end"]})
            if ln.get("text_roman") else [])
    if min_gap <= 0 or not any(ln["start"] is not None for ln in lines):
        return lines
    out: list[dict] = []
    prev_end = 0.0
    for ln in lines:
        start = ln["start"]
        if start is not None and start - prev_end >= min_gap:
            out.append({
                "start": prev_end, "end": start, "text": "", "syls": [], "pieces": [],
                "opposite": bool(ln.get("opposite")),
                "background": False, "dots": True,
                "syls_roman": [], "pieces_roman": [],
            })
        out.append(ln)
        if ln["end"] is not None:
            prev_end = max(prev_end, ln["end"])
        elif start is not None:
            prev_end = max(prev_end, start)
    return out


