LINK_PORT = int(os.environ.get("MILD_LYRICS_LINK_PORT", "8778") or 0)

# TEMPORARY -- a diagnostic for "Mild Lyrics stops following the TTML Editor",
# to be taken out again once that is found. Both programs append to the same
# file, one JSON object a line: what the editor sent, what this window did
# with it, and every track change, reset and command in between.
_FLOG_LOCK = threading.Lock()
_FLOG_PATH: pathlib.Path | None = None


def follow_log(who: str, event: str, **kw) -> None:
    global _FLOG_PATH
    try:
        if _FLOG_PATH is None:
            _FLOG_PATH = app_dir("cache") / "follow.log"
            _FLOG_PATH.parent.mkdir(parents=True, exist_ok=True)
        row = {"t": round(mono(), 3), "wall": time.strftime("%H:%M:%S"),
               "who": who, "ev": event, **kw}
        line = json.dumps(row, default=str, ensure_ascii=False) + "\n"
        with _FLOG_LOCK:
            try:
                if _FLOG_PATH.stat().st_size > 20_000_000:
                    _FLOG_PATH.replace(_FLOG_PATH.with_name("follow.log.1"))
            except OSError:
                pass
            with open(_FLOG_PATH, "a", encoding="utf-8") as f:
                f.write(line)
    except Exception:                                   # noqa: BLE001
        pass


def process_age() -> float | None:
    """Seconds since the OS started this process, the interpreter's own start included."""
    try:
        if sys.platform == "win32":
            import ctypes
            from ctypes import wintypes
            k = ctypes.windll.kernel32
            k.GetCurrentProcess.restype = wintypes.HANDLE
            k.GetProcessTimes.argtypes = [wintypes.HANDLE] + [ctypes.POINTER(wintypes.FILETIME)] * 4
            ft = [wintypes.FILETIME() for _ in range(5)]
            if not k.GetProcessTimes(k.GetCurrentProcess(), *map(ctypes.byref, ft[:4])):
                return None
            k.GetSystemTimeAsFileTime(ctypes.byref(ft[4]))
            v = lambda f: (f.dwHighDateTime << 32) | f.dwLowDateTime
            return (v(ft[4]) - v(ft[0])) / 1e7
        with open("/proc/self/stat") as f:
            ticks = int(f.read().rsplit(")", 1)[1].split()[19])
        with open("/proc/uptime") as f:
            return float(f.read().split()[0]) - ticks / os.sysconf("SC_CLK_TCK")
    except Exception:                                   # noqa: BLE001
        return None


def boot_mark(what: str, **kw) -> None:
    """A startup phase into follow.log ("boot" rows), timed from the process's start."""
    age = process_age()
    follow_log("boot", what, age=None if age is None else round(age, 3), **kw)


def _flog_caller(skip: int = 2, depth: int = 4) -> str:
    """Who called, a few frames up, for the follow log."""
    try:
        st = traceback.extract_stack()[:-skip][-depth:]
        return " < ".join(f"{f.name}:{f.lineno}" for f in reversed(st))
    except Exception:                                   # noqa: BLE001
        return "?"


class LiveLink(QObject):
    """A loopback socket the TTML editor talks to, so a file being timed shows
    on the real player without saving; `state` carries the player's
    offset-applied clock."""

    clear = pyqtSignal()
    seek = pyqtSignal(float)
    follow = pyqtSignal(float, bool, float, float, bool)
    let_go = pyqtSignal()

    def __init__(self, view) -> None:
        super().__init__(view)
        self.view = view
        self.server = None
        self.error = ""
        self._pulse = None
        self._was = None
        if not LINK_PORT:
            return
        from PyQt6.QtNetwork import QHostAddress, QTcpServer
        self.server = QTcpServer(self)
        app = QApplication.instance()
        if app is not None:
            app.aboutToQuit.connect(self.close)
        if not self.server.listen(QHostAddress("127.0.0.1"), LINK_PORT):
            self.error = self.server.errorString()
            self.server = None
            return
        self.server.newConnection.connect(self._accept)

    def close(self) -> None:
        """Stop listening. Safe to call twice."""
        if self.server is not None:
            self.server.close()
            self.server = None

    def _accept(self) -> None:
        """Take the editor's connection and hold it in `_conns` (a Qt-made
        socket held only by its own lambdas is lost to the next gc)."""
        conns = self._connections()
        while self.server and self.server.hasPendingConnections():
            sock = self.server.nextPendingConnection()
            conns[sock] = b""
            sock.readyRead.connect(lambda s=sock: self._read(s))
            sock.disconnected.connect(lambda s=sock: self._closed(s))
            sock.disconnected.connect(self._maybe_let_go)
            sock.disconnected.connect(sock.deleteLater)
        self._watch()

    def _connections(self) -> dict:
        got = getattr(self, "_conns", None)
        if got is None:
            got = self._conns = {}
        return got

    def _closed(self, sock) -> None:
        self._connections().pop(sock, None)
        self._discord_held().discard(sock)

    def _discord_held(self) -> set:
        got = getattr(self, "_discord", None)
        if got is None:
            got = self._discord = set()
        return got

    def editor_discord(self) -> bool:
        """Whether an open TTML Editor is showing its own Discord card, which
        this window's then gives way to (cmd:discord)."""
        return any(s.state() == s.SocketState.ConnectedState
                   for s in self._discord_held())

    def tell_editor(self, msg: dict) -> bool:
        """Send the editor something it did not ask for: a seek or a pause
        made in this window, for the file it is timing against. Rows with an
        "ev" and no "ok", so an editor that does not know them passes them
        by. Whether any editor was there to be told."""
        if self.server is None:
            return False
        line = (json.dumps(msg) + "\n").encode("utf-8")
        told = False
        for sock in list(self._connections()):
            try:
                if sock.state() == sock.SocketState.ConnectedState:
                    sock.write(line)
                    told = True
            except Exception:                           # noqa: BLE001
                pass
        return told

    def _maybe_let_go(self) -> None:
        if not [s for s in self.findChildren(QObject)
                if s.__class__.__name__ == "QTcpSocket"
                and s.state() == s.SocketState.ConnectedState]:
            follow_log("player", "socket-gone-let-go")
            self.view._rev_auto_editor = False
            self.let_go.emit()
            self.view.editor_closed()

    # ---------------------------------------------------------------- jumps
    def _watch(self) -> None:
        """Tell the editor when the song moves, at once, and say something
        every SAY_EVERY anyway."""
        if getattr(self, "_pulse", None) is not None:
            return
        self._pulse = QTimer(self)
        self._pulse.timeout.connect(self._maybe_announce)
        self._pulse.start(50)
        self._was = None

    def _maybe_announce(self) -> None:
        if self.server is None:
            return
        socks = [s for s in self.findChildren(QObject)
                 if s.__class__.__name__ == "QTcpSocket"
                 and s.state() == s.SocketState.ConnectedState]
        if not socks:
            self._was = None
            return
        v = self.view
        now, pos = mono(), float(v.position())
        state = (v.clock.tid, v.clock.status)
        if self._was is not None:
            was_pos, was_at, was_state = self._was
            drift = pos - (was_pos + (now - was_at
                                      if was_state[1] == "Playing" else 0.0))
            moved = (abs(drift) > SAY_DRIFT or state != was_state
                     or now - was_at >= SAY_EVERY)
        else:
            moved = True
        if not moved:
            return
        self._was = (pos, now, state)
        msg = {"ok": True, "tid": v.clock.tid or "", "status": v.clock.status,
               "title": str(v.clock.meta.get("title") or ""),
               "artist": str(v.clock.meta.get("artist") or ""),
               "length": float(v.clock.meta.get("length") or 0.0),
               "pos": pos, "offset": float(v.track_offset()),
               "base": float(v.offset),
               "track": round(float(v.track_offset()) - float(v.offset), 4),
               "at": now, "live": v.live_shown(),
               "volume": v.spotify_volume(),
               # Same shape as cmd:state: a pulse without "mine" sent the editor to Spotify's clock (0s)
               **v.own_player_state()}
        line = (json.dumps(msg) + "\n").encode("utf-8")
        for sock in socks:
            try:
                sock.write(line)
            except Exception:
                pass

    def _read(self, sock) -> None:
        """Whole lines only, decoded once whole (bytes buffered)."""
        held = self._connections()
        new = bytes(sock.readAll())
        buf = held.get(sock, b"") + new
        follow_log("player", "sock-read", bytes=len(new), held=len(buf),
                   lines=buf.count(b"\n"), sock=id(sock))
        while b"\n" in buf:
            row, buf = buf.split(b"\n", 1)
            text = row.decode("utf-8", "replace").strip()
            if text:
                self._handle(sock, text)
        if sock in held:
            held[sock] = buf

    def _handle(self, sock, row: str) -> None:
        try:
            msg = json.loads(row)
        except Exception:
            return
        cmd = str(msg.get("cmd") or "")
        out: dict = {"ok": True}
        if cmd not in ("state", "doc", "source_doc"):
            follow_log("player", "recv", cmd=cmd,
                       **{k: v for k, v in msg.items()
                          if k not in ("cmd", "ttml")},
                       ttml_len=len(str(msg.get("ttml") or "")) or None)
        if cmd == "state":
            v = self.view
            out.update(tid=v.clock.tid or "", status=v.clock.status,
                       title=str(v.clock.meta.get("title") or ""),
                       artist=str(v.clock.meta.get("artist") or ""),
                       length=float(v.clock.meta.get("length") or 0.0),
                       pos=float(v.position()),
                       offset=float(v.track_offset()),
                       base=float(v.offset),
                       track=round(float(v.track_offset()) - float(v.offset), 4),
                       at=mono(),
                       live=v.live_shown(),
                       volume=v.spotify_volume(),
                       **v.own_player_state())
        elif cmd == "ttml":
            want = str(msg.get("tid") or "")
            if want and self.view.clock.tid and want != self.view.clock.tid:
                out = {"ok": False, "why": "a different song is playing"}
            else:
                # Read off the window's thread; a document that cannot be
                # read comes back to the editor as "push-failed".
                self.view.show_live_lyric_soon(
                    str(msg.get("ttml") or ""),
                    str(msg.get("name") or "the editor"))
        elif cmd in ("doc", "source_doc"):
            v = self.view
            mine = v.live_shown()
            body = v.body
            whose = str(getattr(v, "source", "") or "")
            why = ""
            if cmd == "source_doc" and mine:
                body = getattr(v, "own_body", None)
                mine = False
                if not body:
                    why = ("this song's own lyrics are not loaded — the "
                           "editor's are")
            if not body and not why:
                why = "the player has no lyrics loaded"
            if not why and LS.spicy_made(body):
                out = {"ok": False, "spicy": True,
                       "why": "it came from Spicy Lyrics, which is not "
                              "handed to the editor"}
            elif why:
                out = {"ok": False, "why": why}
            else:
                try:
                    out = {"ok": True, "ttml": SL.render(body, "ttml"),
                           "source": whose,
                           "live": mine,
                           "from": str(getattr(v, "dropped_from", "") or ""),
                           "tid": v.clock.tid or "",
                           "title": str(v.clock.meta.get("title") or ""),
                           "artist": str(v.clock.meta.get("artist") or "")}
                except Exception as exc:              # noqa: BLE001
                    out = {"ok": False,
                           "why": f"could not render it — {type(exc).__name__}"}
        elif cmd == "follow":
            if msg.get("stop"):
                self.let_go.emit()
            else:
                try:
                    self.follow.emit(float(msg.get("pos") or 0.0),
                                     bool(msg.get("playing")),
                                     float(msg.get("rate") or 1.0),
                                     float(msg.get("at") or 0.0),
                                     bool(msg.get("held")))
                except (TypeError, ValueError):
                    out = {"ok": False, "why": "not a position"}
        elif cmd == "volume":
            try:
                self.view.volume_from_editor(float(msg.get("volume")))
            except (TypeError, ValueError):
                out = {"ok": False, "why": "not a volume"}
        elif cmd == "clear":
            self.clear.emit()
        elif cmd == "discord":
            held = self._discord_held()
            (held.add if msg.get("on") else held.discard)(sock)
        elif cmd == "seek":
            try:
                self.seek.emit(float(msg.get("pos")) + self.view.track_offset())
            except (TypeError, ValueError):
                out = {"ok": False, "why": "no position"}
        elif cmd == "control":                      # the editor following Mild Lyrics' own player
            name = str(msg.get("name") or "")
            if name in ("PlayPause", "Next", "Previous"):
                self.view.player_do(name)
            else:
                out = {"ok": False, "why": f"unknown control {name!r}"}
        else:
            out = {"ok": False, "why": f"unknown command {cmd!r}"}
        try:
            sock.write((json.dumps(out) + "\n").encode("utf-8"))
        except Exception:
            pass


class Readings(list):
    """Per-row reading marks, and where their band sits: "over" (furigana),
    or the periodic numbers' "under" or "corner"."""
    place = "over"


class ReadRows(list):
    """Wrapped rows carrying their own readings: the romanisation's, which
    rides outside layout_line's tuple (see roman_band)."""
    ruby, rufm = (), None


def _spread(marks: list, rufm, edge: float, gap: float = 2.0) -> list:
    """Push ruby readings apart where they would overlap, shifting the run back
    from the right edge if needed."""
    if len(marks) < 2:
        return marks
    wide = [advance(rufm, m[1]) for m in marks]
    left = [m[0] - w / 2 for m, w in zip(marks, wide)]
    for i in range(1, len(left)):
        left[i] = max(left[i], left[i - 1] + wide[i - 1] + gap)
    over = left[-1] + wide[-1] - edge
    if over > 0:
        left[-1] -= over
        for i in range(len(left) - 2, -1, -1):
            left[i] = min(left[i], left[i + 1] - wide[i] - gap)
    return [(x + w / 2, m[1], m[2], m[3])
            for x, w, m in zip(left, wide, marks)]


# --------------------------------------------------------------------------
SEARCH_MAX = 300
EDIT_MAX = 2000


class Field:
    """One hand-drawn line of editable text: caret, selection, clipboard keys;
    `at`, `fm` and `rect` come from the last paint."""

    def __init__(self, text: str = "", limit: int | None = None) -> None:
        self.limit = limit
        self.clipped = False
        self.text = text if limit is None else text[:limit]
        self.caret = len(self.text)
        self.sel: int | None = None
        self.picked: tuple[int, int] | None = None   # double-clicked; drags by words
        self.at = 0.0
        self.fm: QFontMetricsF | None = None
        self.rect: QRectF | None = None

    def set_text(self, text: str) -> None:
        """Replace the lot: caret at the end, nothing selected."""
        if self.limit is not None and len(text) > self.limit:
            text, self.clipped = text[:self.limit], True
        self.text = text
        self.caret, self.sel, self.picked = len(text), None, None

    def span(self) -> tuple[int, int]:
        """The selected range, low to high. Empty when the two ends agree."""
        a = self.caret if self.sel is None else self.sel
        return (min(a, self.caret), max(a, self.caret))

    def replace_at(self, lo: int, hi: int, text: str) -> None:
        lo = max(0, min(len(self.text), lo))
        hi = max(lo, min(len(self.text), hi))
        if self.limit is not None:
            room = self.limit - len(self.text) + (hi - lo)
            if len(text) > room:
                text, self.clipped = text[:max(0, room)], True
        self.text = self.text[:lo] + text + self.text[hi:]
        self.caret, self.sel, self.picked = lo + len(text), None, None

    def replace(self, text: str) -> None:
        lo, hi = self.span()
        self.replace_at(lo, hi, text)

    def select_all(self) -> None:
        self.sel, self.caret = 0, len(self.text)

    def paste(self) -> bool:
        """The clipboard, as one line. False when there was nothing in it."""
        got = (QApplication.clipboard().text() or "").replace("\n", " ").strip()
        if not got:
            return False
        self.replace(got)
        return True

    def word(self, at: int, step: int) -> int:
        """One word-hop from `at`: over the spaces, then over the word they
        were against, which is what a control-arrow means everywhere else."""
        if step < 0:
            while at > 0 and self.text[at - 1].isspace():
                at -= 1
            while at > 0 and not self.text[at - 1].isspace():
                at -= 1
            return at
        n = len(self.text)
        while at < n and self.text[at].isspace():
            at += 1
        while at < n and not self.text[at].isspace():
            at += 1
        return at

    def go(self, at: int, keep: bool) -> None:
        """Put the caret here, growing the selection or dropping it."""
        if keep and self.sel is None:
            self.sel = self.caret
        elif not keep:
            self.sel = None
        self.caret = max(0, min(len(self.text), at))

    def key(self, ev) -> bool:
        """Whatever a text box does with this key press.

        False when it does nothing with it, so the caller can go on to its
        own meaning for the key -- which is how Up and Down still walk a
        results list while the caret lives in the box above it.
        """
        k, mods = ev.key(), ev.modifiers()
        ctrl = bool(mods & Qt.KeyboardModifier.ControlModifier)
        alt = bool(mods & Qt.KeyboardModifier.AltModifier)
        keep = bool(mods & Qt.KeyboardModifier.ShiftModifier)
        lo, hi = self.span()
        if ctrl and not alt:
            if k == Qt.Key.Key_A:
                self.select_all()
                return True
            if k in (Qt.Key.Key_C, Qt.Key.Key_X):
                if hi > lo:
                    QApplication.clipboard().setText(self.text[lo:hi])
                    if k == Qt.Key.Key_X:
                        self.replace("")
                return True
            if k == Qt.Key.Key_V:
                self.paste()
                return True
        if k in (Qt.Key.Key_Left, Qt.Key.Key_Right):
            back = k == Qt.Key.Key_Left
            if ctrl:
                at = self.word(self.caret, -1 if back else 1)
            elif hi > lo and not keep:
                at = lo if back else hi
            else:
                at = self.caret + (-1 if back else 1)
            self.go(at, keep)
            return True
        if k in (Qt.Key.Key_Home, Qt.Key.Key_End):
            self.go(0 if k == Qt.Key.Key_Home else len(self.text), keep)
            return True
        if k in (Qt.Key.Key_Backspace, Qt.Key.Key_Delete):
            back = k == Qt.Key.Key_Backspace
            if hi > lo:
                self.replace("")
            elif ctrl:
                at = self.word(self.caret, -1 if back else 1)
                self.replace_at(min(at, self.caret), max(at, self.caret), "")
            elif back:
                self.replace_at(self.caret - 1, self.caret, "")
            else:
                self.replace_at(self.caret, self.caret + 1, "")
            return True
        if ev.text() and ev.text().isprintable() and (alt or not ctrl):
            self.replace(ev.text())
            return True
        return False

    def laid_out(self, at: float, fm, rect) -> None:
        """Called by the painter: x of character 0, the metrics it was drawn
        in, and the box a click has to land in to be this field's."""
        self.at, self.fm, self.rect = at, fm, rect

    def index_at(self, x: float) -> int:
        """The caret gap nearest this x in the last frame's geometry, by
        bisecting prefix widths, then checking the last few one by one."""
        if self.fm is None or not self.text:
            return 0
        want = x - self.at
        lo, hi = 0, len(self.text)
        while hi - lo > 4:
            mid = (lo + hi) // 2
            if self.fm.horizontalAdvance(self.text[:mid]) < want:
                lo = mid
            else:
                hi = mid
        best, near = lo, abs(want - self.fm.horizontalAdvance(self.text[:lo]))
        for i in range(lo + 1, hi + 1):
            gap = abs(want - self.fm.horizontalAdvance(self.text[:i]))
            if gap < near:
                best, near = i, gap
        return best

    def under(self, pos) -> bool:
        return self.rect is not None and self.rect.contains(pos)

    def press(self, pos, keep: bool = False) -> bool:
        """Put the caret where the click landed. False if it landed elsewhere."""
        if not self.under(pos):
            return False
        self.picked = None
        self.go(self.index_at(pos.x()), keep)
        return True

    def drag_to(self, pos) -> None:
        """Carry on a selection the mouse is dragging out -- by whole words
        after a double click, keeping the word that was picked."""
        at = self.index_at(pos.x())
        if self.picked is not None and self.text:
            lo, hi = self.picked
            if at > hi:
                self.sel, self.caret = lo, self._run(at - 1)[1]
            elif at < lo:
                self.sel, self.caret = hi, self._run(at)[0]
            else:
                self.sel, self.caret = lo, hi
            return
        if self.sel is None:
            self.sel = self.caret
        self.caret = at

    def _run(self, at: int) -> tuple[int, int]:
        """The run of word or of blank holding character `at`."""
        n = len(self.text)
        at = max(0, min(at, n - 1))
        blank = self.text[at].isspace()
        lo = hi = at
        while lo > 0 and self.text[lo - 1].isspace() == blank:
            lo -= 1
        while hi < n and self.text[hi].isspace() == blank:
            hi += 1
        return lo, hi

    def pick_word(self, pos) -> bool:
        """Double click: the run of word or of blank under the pointer."""
        if not self.under(pos) or not self.text:
            return self.under(pos)
        n = len(self.text)
        at = min(self.index_at(pos.x()), n - 1)
        if self.text[at].isspace() and at > 0 and not self.text[at - 1].isspace():
            at -= 1
        self.sel, self.caret = self.picked = self._run(at)
        return True


class _WakeFilter(QObject):
    """LyricsView.saw_event, as a filter: an event() override held the GIL through Qt's whole
    repaint and swap, starving every other thread (60Hz videos at 13fps) -- notes 2026-10-22."""

    def __init__(self, view) -> None:
        super().__init__(view)
        self.view = view

    def eventFilter(self, obj, ev) -> bool:                # noqa: N802 (Qt name)
        if obj is self.view:
            self.view.saw_event(ev)
        return False


class _VsyncFilter(QObject):
    """Hands the window's UpdateRequest -- on Wayland, the compositor's frame
    callback -- to LyricsView._vsync_frame while it is waiting for one, and
    keeps it: let through, Qt's widget window answers it by repainting the
    whole top-level widget, which the step's own update() has already asked
    for in the ordinary way. See frame_clock, where the editor measured it."""

    def __init__(self, view) -> None:
        super().__init__(view)
        self.view = view

    def eventFilter(self, obj, ev) -> bool:                # noqa: N802 (Qt name)
        if ev.type() == QEvent.Type.UpdateRequest:
            v = self.view
            if v._vsync_live and obj is v._vsync_handle:
                v._vsync_frame()
                return True
        return False


class LyricsView(QWidget):
    art_ready = pyqtSignal(str, object)
    yt_ready = pyqtSignal(str, object, object)      # tid, the body it came from, that body on the video's clock
    mv_found = pyqtSignal(object, object)           # (tid, upload), (video id, stream link, length) or None
    mv_mapped = pyqtSignal(object, object, object)  # (tid, upload), (the body, the song's source) it was read off, stretches or None
    mv_next_found = pyqtSignal(object, str)         # the next song (as _mv_next_song), its video id or ""
    mv_next_mapped = pyqtSignal(object, object)     # the next song, its Store job (vid, pieces)
    face_ready = pyqtSignal(str, object)
    genius_page_ready = pyqtSignal(str, str)
    update_found = pyqtSignal(object)
    update_done = pyqtSignal(bool, str)
    changelog_ready = pyqtSignal(object)
    spotify_up = pyqtSignal()
    font_ready = pyqtSignal(str)
    device_ready = pyqtSignal(str, str)
    measured = pyqtSignal(int, str, object)
    own_heard = pyqtSignal(str, str, object)    # est key, audio, (fit, vocal rows, lyric_offset)
    live_read = pyqtSignal(object)      # (gen, body, lines, name, error)

    query = property(lambda s: s.q_field.text,
                     lambda s, v: s.q_field.set_text(v))
    bq = property(lambda s: s.bq_field.text,
                  lambda s, v: s.bq_field.set_text(v))
    edit_text = property(lambda s: s.edit_field.text,
                         lambda s, v: s.edit_field.set_text(v))

    frame_timer = None
    gl_canvas = None

    def __init__(self, args) -> None:
        super().__init__()
        self._busy_at = mono()
